def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    try:
        # Handle sequence types (list/tuple) representing coordinates
        if isinstance(value, (list, tuple)):
            if len(value) < 2:
                raise ValueError("Coordinate sequence must contain at least two elements for x and y.")
            point_dict = {"x": value[0], "y": value[1]}
            if len(value) > 2:
                point_dict["z"] = value[2]
            return point_dict

        # Handle dicts directly (assume already dehydrated)
        if isinstance(value, dict):
            return dict(value)

        # Handle objects with .x and .y attributes (e.g., shapely.geometry.Point)
        if hasattr(value, "x") and hasattr(value, "y"):
            point_dict = {"x": getattr(value, "x"), "y": getattr(value, "y")}
            if hasattr(value, "z"):
                point_dict["z"] = getattr(value, "z")
            return point_dict

        # Handle objects with latitude/longitude attributes
        if hasattr(value, "latitude") and hasattr(value, "longitude"):
            point_dict = {
                "latitude": getattr(value, "latitude"),
                "longitude": getattr(value, "longitude"),
            }
            return point_dict

        # Unsupported type
        raise TypeError(f"Unsupported type {type(value)} for point dehydration.")

    except Exception as ex:
        raise ValueError(f"Error dehydrating point: {ex}") from ex

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Attempt to retrieve the underlying dictionary holding the record data
        data = getattr(self, "_data", None)
        if data is None:
            data = getattr(self, "data", None)
        if data is None:
            # If the instance itself is a mapping, use it directly
            if isinstance(self, dict):
                data = self
            else:
                raise AttributeError("Unable to locate record data")
        if not isinstance(data, dict):
            raise TypeError(f"Expected a dictionary for record data, got {type(data).__name__}")
        return list(data.keys())
    except Exception:
        # In case of any unexpected issue, fall back to an empty list
        return []

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Ensure the class has a registry of handlers. If not present,
    # initialize an empty dict. The registry is expected to be a
    # mapping: { (major, minor): HandlerClass, ... }
    if not hasattr(cls, "_protocol_handlers"):
        cls._protocol_handlers = {}

    handlers = cls._protocol_handlers

    # Validate the protocol_version argument
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError(
            "protocol_version must be a tuple of integers or None, "
            f"got {type(protocol_version).__name__}"
        )

    # If no specific version is requested, return all handlers
    if protocol_version is None:
        return dict(handlers)

    # Return a dictionary containing only the requested version, if it exists
    if protocol_version in handlers:
        return {protocol_version: handlers[protocol_version]}
    return {}

def unit_of_work(metadata=None, timeout=None):
    """Decorator that adds optional metadata and timeout support for transaction functions.

    It can be used with or without parentheses:

    .. code-block:: python

        @unit_of_work
        def tx_func(tx):
            ...

        @unit_of_work(metadata={'key': 'value'}, timeout=5.0)
        def tx_func(tx):
            ...

    Parameters
    ----------
    metadata : dict, optional
        Metadata dictionary to attach to the transaction. Must be a plain dict or None.
    timeout : float or None, optional
        Transaction timeout in seconds. Must be a non-negative number or None.
    """
    import functools

    # Support calling without parentheses: @unit_of_work
    if callable(metadata) and timeout is None:
        # metadata actually refers to the function
        func = metadata
        metadata = None
        timeout = None

        @functools.wraps(func)
        def wrapper(tx, *args, **kwargs):
            return func(tx, *args, **kwargs)

        return wrapper

    def decorator(func):
        @functools.wraps(func)
        def wrapper(tx, *args, **kwargs):
            # Validate metadata
            if metadata is not None and not isinstance(metadata, dict):
                raise TypeError("metadata must be a dict or None")
            # Validate timeout
            if timeout is not None:
                if not isinstance(timeout, (int, float)):
                    raise TypeError("timeout must be a number or None")
                if timeout < 0:
                    raise ValueError("timeout cannot be negative")

            # Attempt to set metadata and timeout on the transaction object if supported.
            # The actual implementation depends on the transaction API.
            if hasattr(tx, "metadata"):
                tx.metadata = metadata
            if hasattr(tx, "timeout"):
                tx.timeout = timeout

            return func(tx, *args, **kwargs)

        return wrapper

    return decorator

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        seq = list(self)
    except TypeError:
        raise TypeError(f"object of type {type(self).__name__} is not iterable")
    for idx, item in enumerate(seq):
        if item == key:
            return idx
    raise ValueError(f"{key!r} is not in the sequence")

def values(self, *keys):
        """
        Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        try:
            # Attempt to obtain items as a list of (key, value) tuples
            items = []

            # Check if the instance itself is a dict-like object
            if isinstance(self, dict):
                items = list(self.items())

            # If the instance has an items() method (like collections.abc.Mapping)
            elif hasattr(self, "items") and callable(self.items):
                items = list(self.items())

            # Fallback: use the instance's __dict__ to collect attributes
            elif hasattr(self, "__dict__"):
                # Exclude private/internal attributes and callables
                for attr_name, attr_value in self.__dict__.items():
                    if not attr_name.startswith("_") and not callable(attr_value):
                        items.append((attr_name, attr_value))

            # If still empty, try to iterate over the object assuming it yields values
            if not items:
                # Try treating the object itself as an iterable of values
                try:
                    iter_result = list(self)
                    # we cannot provide keys, so just return these values
                    return iter_result
                except TypeError:
                    # Object is not iterable; cannot extract values
                    return []

            # If no specific keys requested, return all values
            if not keys:
                return [val for _, val in items]

            # Collect values based on provided keys or indexes
            result = []
            for k in keys:
                # Handle integer indexes (including negative indices)
                if isinstance(k, int):
                    idx = k
                    if idx < 0:
                        idx = len(items) + idx
                    if 0 <= idx < len(items):
                        result.append(items[idx][1])
                    else:
                        # Index out of range: skip or could raise IndexError
                        continue
                else:
                    # Interpret as a key lookup
                    for key, value in items:
                        if key == k:
                            result.append(value)
                            break
                    else:
                        # Key not found: skip or could raise KeyError
                        continue
            return result
        except Exception:
            # Return empty list on any unexpected error
            return []

