def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Determine ordered list of field names
    fieldnames = None
    if hasattr(self, "_fields") and isinstance(self._fields, (list, tuple)):
        fieldnames = list(self._fields)
    elif hasattr(self, "fields") and isinstance(self.fields, (list, tuple)):
        fieldnames = list(self.fields)
    else:
        # fallback: use keys from the instance's attribute dictionary
        fieldnames = list(self.__dict__.keys())

    # Helper to fetch value for a given field name
    def _get_value(name):
        return getattr(self, name, None)

    # If no specific keys are requested, return all fields
    if not keys:
        return {name: _get_value(name) for name in fieldnames}

    result = {}
    for k in keys:
        if isinstance(k, int):
            idx = k
            if idx < 0 or idx >= len(fieldnames):
                raise IndexError(
                    f"Index {idx} out of bounds for record with {len(fieldnames)} fields"
                )
            name = fieldnames[idx]
            result[name] = _get_value(name)
        else:
            name = k
            if name in fieldnames:
                result[name] = _get_value(name)
            else:
                result[name] = None
    return result
