def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # --- Validate parameters --------------------------------------------------
    if mode is not None:
        if not isinstance(mode, str):
            raise TypeError("mode must be a string")
        mode_val = mode.upper()
        if mode_val not in ("READ", "WRITE"):
            raise ValueError("mode must be 'READ' or 'WRITE'")
    else:
        mode_val = None

    if bookmarks is not None:
        if not hasattr(bookmarks, "__iter__") or isinstance(bookmarks, (str, bytes)):
            raise TypeError("bookmarks must be an iterable of strings")
        bookmarks_val = []
        for b in bookmarks:
            if not isinstance(b, str):
                raise TypeError("each bookmark must be a string")
            bookmarks_val.append(b)
    else:
        bookmarks_val = None

    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dictionary")

    if timeout is not None:
        try:
            timeout_val = float(timeout)
        except Exception:
            raise TypeError("timeout must be a number")
    else:
        timeout_val = None

    if db is not None and not isinstance(db, str):
        raise TypeError("db must be a string")

    if imp_user is not None and not isinstance(imp_user, str):
        raise TypeError("imp_user must be a string")

    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise TypeError("dehydration_hooks must be a dictionary")

    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise TypeError("hydration_hooks must be a dictionary")

    # --- Build the BEGIN message ---------------------------------------------
    message = {
        "type": "BEGIN",
        "mode": mode_val,
        "bookmarks": bookmarks_val,
        "metadata": metadata,
        "timeout": timeout_val,
        "db": db,
        "imp_user": imp_user
    }

    # Remove keys with None values
    message = {k: v for k, v in message.items() if v is not None}

    # --- Enqueue the message ---------------------------------------------------
    try:
        if not hasattr(self, "_out_queue"):
            raise AttributeError("The object does not have an output queue")
        self._out_queue.append(message)
    except Exception as exc:
        raise RuntimeError("Failed to enqueue BEGIN message") from exc

    # --- Construct and return the Response -------------------------------------
    try:
        # Assume a Response class exists and accepts these parameters
        return Response(
            connection=self,
            handlers=handlers,
            dehydration_hooks=dehydration_hooks,
            hydration_hooks=hydration_hooks
        )
    except Exception as exc:
        raise RuntimeError("Failed to create Response object") from exc

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Basic validation of inputs
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple of field names")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")

    # Prepare class attributes. Each field is defaulted to None.
    attrs = {f: None for f in fields if isinstance(f, str)}
    # Store the SRID mapping as a protected attribute
    attrs["_srid_map"] = srid_map

    # Try to find a Point base class in the global namespace; fall back to object.
    PointBase = globals().get("Point", object)

    # The constructor just assigns keyword values to the fields.
    def __init__(self, *args, **kwargs):
        # Ignore positional args since we have no knowledge of the base __init__ signature.
        for key in fields:
            if key in kwargs:
                setattr(self, key, kwargs[key])

    attrs["__init__"] = __init__

    # Dynamically create the new class.
    new_cls = type(name, (PointBase,), attrs)
    return new_cls

def deprecated(message):
    """Decorator that warns when a function or method is used.\n\n    :param message: The deprecation message that will be displayed.\n    :type message: str\n    :raises TypeError: If the provided message is not a string.\n    :return: A decorator that wraps the original function.\n    """
    if not isinstance(message, str):
        raise TypeError("deprecation message must be a string")
    def decorator(func):
        warning_module = __import__("warnings")
        wraps_module = __import__("functools")
        @wraps_module.wraps(func)
        def wrapper(*args, **kwargs):
            warning_module.warn(message, category=warning_module.DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("parse_version expects a string argument")
    s = s.strip()
    if not s:
        return ()
    nums = []
    for part in s.split('.'):
        num_str = ''
        for char in part:
            if char.isdigit():
                num_str += char
            else:
                break
        if num_str:
            try:
                nums.append(int(num_str))
            except ValueError:
                # Should not happen since we only accumulate digits
                continue
    return tuple(nums)

def cached(cache, key=None, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    # Determine the key generating function
    if key is None:
        def default_key(args, kwargs):
            """Generate a hashable key from args and kwargs."""
            try:
                # Direct hash if all components are hashable
                return hash((args, tuple(sorted(kwargs.items()))))
            except TypeError:
                # Fallback: use string representation which is hashable
                return str((args, frozenset(kwargs.items())))
        key_func = default_key
    else:
        # Ensure key is callable
        if not callable(key):
            raise TypeError("`key` must be a callable")
        key_func = key

    def decorator(func):
        def wrapper(*args, **kwargs):
            # Build the cache key
            try:
                k = key_func(args, kwargs)
            except Exception as exc:
                raise ValueError(f"Error generating cache key: {exc}") from exc

            cached_value = None
            # Attempt to retrieve from cache
            try:
                if lock:
                    with lock:
                        cached_value = cache.get(k)
                else:
                    cached_value = cache.get(k)
            except Exception:
                # Ignore cache retrieval errors; proceed to compute
                cached_value = None

            if cached_value is not None:
                return cached_value

            # Compute the function result
            try:
                result = func(*args, **kwargs)
            except Exception:
                # Propagate exception from the wrapped function
                raise

            # Store the result in cache
            try:
                if lock:
                    with lock:
                        cache.set(k, result)
                else:
                    cache.set(k, result)
            except Exception:
                # Ignore cache storage errors
                pass

            return result

        # Preserve the wrapped function's name and docstring if possible
        wrapper.__name__ = getattr(func, "__name__", "wrapper")
        wrapper.__doc__ = getattr(func, "__doc__")
        return wrapper

    return decorator

def setdefault(self, key, default=None):
        """
        D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
        """
        try:
            return self[key]
        except KeyError:
            self[key] = default
            return default

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=None, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    if cache is None:
        raise TypeError("'cache' must be provided and cannot be None")

    # Ensure lock is a context manager if provided
    if lock is not None and not (hasattr(lock, "__enter__") and hasattr(lock, "__exit__")):
        raise TypeError("'lock' must be a context manager")

    # Determine how the cache key is computed
    if key is None:
        def key_func(*args, **kwargs):
            return hash((args, frozenset(sorted(kwargs.items()))))
    elif not callable(key):
        raise TypeError("'key' must be a callable that returns a hashable value")
    else:
        key_func = key

    def decorator(func):
        # Import functools locally to avoid top‑level imports
        import functools
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            k = key_func(*args, **kwargs)
            # Fast path: try to retrieve from cache
            try:
                return cache[k]
            except KeyError:
                pass
            except Exception as exc:
                # If cache lookup fails for other reasons, propagate the error
                raise RuntimeError(f"Cache access failed: {exc}") from exc

            # Compute result, optionally under a lock
            if lock is not None:
                with lock:
                    # Double‑check to avoid race conditions
                    if k in cache:
                        return cache[k]
                    try:
                        result = func(*args, **kwargs)
                    except Exception:
                        # Do not cache on exception
                        raise
                    cache[k] = result
                    return result
            else:
                try:
                    result = func(*args, **kwargs)
                except Exception:
                    # Do not cache on exception
                    raise
                cache[k] = result
                return result

        return wrapper

    return decorator

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    import traceback, os
    if not isinstance(e, BaseException):
        raise TypeError("e must be an exception instance")
    if not isinstance(max_level, int) or max_level <= 0:
        raise ValueError("max_level must be a positive integer")
    if not isinstance(max_path_level, int) or max_path_level <= 0:
        raise ValueError("max_path_level must be a positive integer")
    try:
        te = traceback.TracebackException.from_exception(e)
        if not te.stack:
            return f"{te.exc_type.__name__}: {te.exc_value}"
        stack_frames = list(te.stack)[-max_level:]
        lines = ["Traceback (most recent call last):"]
        for frame in stack_frames:
            path = frame.filename
            parts = path.split(os.sep)
            if len(parts) > max_path_level:
                path = os.sep.join(parts[-max_path_level:])
            line_text = (frame.line or "").strip()
            lines.append(f'  File "{path}", line {frame.lineno}, in {frame.name}')
            if line_text:
                lines.append(f"    {line_text}")
        lines.append(f"{te.exc_type.__name__}: {te.exc_value}")
        return "\n".join(lines)
    except Exception:
        return f"{type(e).__name__}: {e}"

@staticmethod
def file_to_textbuffer(file_name, encoding):
    """
    Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
    CAUTION : This will read the whole file IN MEMORY.
    :param file_name: File name.
    :type file_name: str
    :param encoding: Encoding to use.
    :type encoding: str
    :return: A text buffer or None in case of error.
    :rtype str
    """
    # Validate input types
    if not isinstance(file_name, str) or not isinstance(encoding, str):
        return None
    try:
        with open(file_name, 'r', encoding=encoding) as f:
            return f.read()
    except (FileNotFoundError, PermissionError, OSError, UnicodeDecodeError, ValueError):
        return None
    except Exception:
        # Catch all other unexpected exceptions and return None
        return None

@staticmethod
    def is_file_exist(file_name):
        """
        Check if file name exist.
        :param file_name: File name.
        :type file_name: str
        :return: Return true (exist), false (do not exist, or invalid file name)
        :rtype bool
        """
        # Import inside function to avoid exterior dependencies
        try:
            import os
        except Exception:
            return False

        # Validate input
        if not isinstance(file_name, str) or not file_name.strip():
            return False

        try:
            return os.path.isfile(file_name)
        except Exception:
            return False

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
        """
        Return attribute names and descriptions defined by interface.
        The method inspects the instance or its class for attributes and
        attempts to gather descriptive docstrings. If ``all`` is False,
        only public attributes that are not callable are returned.
        """
        results = {}
        try:
            # Determine source for attributes: instance dict first, then class dict
            source_attrs = {}
            # Instance attributes
            if hasattr(self, '__dict__'):
                source_attrs.update(self.__dict__)
            # Class attributes
            cls = self.__class__
            if hasattr(cls, '__dict__'):
                source_attrs.update(cls.__dict__)
            # Optionally filter only attributes that are defined as part of the interface
            # Here we assume that interface attributes are those that do not start with underscore
            for name, value in source_attrs.items():
                if not name.startswith('_'):
                    if not callable(value):
                        # Try to get description from docstring of the attribute if it's a property, method, or has __doc__
                        desc = None
                        try:
                            attr_obj = getattr(self, name)
                        except Exception:
                            attr_obj = value
                        if hasattr(attr_obj, '__doc__') and attr_obj.__doc__:
                            desc = attr_obj.__doc__.strip()
                        else:
                            # Fallback: if the value itself has a description attribute
                            if hasattr(value, 'description'):
                                desc = str(value.description)
                            else:
                                desc = ''
                        results[name] = desc
            # If all=True, also include private and callable attributes
            if all:
                for name, value in source_attrs.items():
                    if name.startswith('_'):
                        if not callable(value):
                            desc = ''
                            if hasattr(value, '__doc__') and value.__doc__:
                                desc = value.__doc__.strip()
                            results[name] = desc
        except Exception:
            # In case of any unexpected error, return empty dict
            return {}
        return results

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Validate the 'all' argument
    if not isinstance(all, bool):
        raise TypeError(f"'all' must be a bool, got {type(all).__name__}")

    cls = getattr(self, "__class__", None)
    if cls is None:
        raise AttributeError("Object does not have a class; cannot determine attributes.")

    # Helper to collect attribute names from a single class
    def _collect(cls_obj):
        attrs = set()
        # Include attributes defined in __dict__ that are not callables or private/dunder names
        for name, value in getattr(cls_obj, "__dict__", {}).items():
            if name.startswith("_") or callable(value):
                continue
            attrs.add(name)
        # Include attributes declared via annotations (which may have no default values)
        annotations = getattr(cls_obj, "__annotations__", {})
        for name in annotations:
            if name.startswith("_"):
                continue
            attrs.add(name)
        return attrs

    if not all:
        return sorted(_collect(cls))

    # If 'all' is True, gather attributes from all base classes in the MRO except 'object'
    all_attrs = set()
    for base in cls.__mro__:
        if base is object:
            continue
        all_attrs.update(_collect(base))
    return sorted(all_attrs)

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        # Attempt to call the complementary function if it exists
        required = _c_optimizations_required()
        # Ensure we interpret truthiness correctly
        return not bool(required)
    except Exception:
        # If we can't determine, default to ignoring C optimizations
        return True

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        pure_python = PURE_PYTHON
    except NameError:
        # If the flag is not defined, fall back to assuming pure python is not
        # in use, i.e., the C optimizations are required.
        pure_python = False

    # Normalise possible string representations to a boolean.
    if isinstance(pure_python, str):
        pure_python = pure_python.strip().lower() in {"1", "true", "yes"}
    else:
        pure_python = bool(pure_python)

    # C optimisations are required only when we are not forced to use pure
    # Python.
    return not pure_python

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value* or with *make_bins()* (depending on the initialization).
    """
    # Reset current context
    try:
        self.context = {}
    except Exception as exc:
        # If the histogram does not expose a 'context' attribute,
        # we still want to keep semantic consistency by creating one.
        self.context = {}
    # Reinitialize bins
    try:
        init_val = getattr(self, "initial_value", None)
        if init_val is not None:
            # Preserve existing bin structure if present
            existing_bins = getattr(self, "bins", None)
            if existing_bins is not None and isinstance(existing_bins, (list, tuple)):
                num_bins = len(existing_bins)
                self.bins = [init_val] * num_bins if num_bins > 0 else []
            else:
                # No existing bins; create a single-bin histogram
                self.bins = [init_val]
        else:
            make_bins_fn = getattr(self, "make_bins", None)
            if callable(make_bins_fn):
                self.bins = make_bins_fn()
            else:
                # Fallback to an empty bins list
                self.bins = []
    except Exception as exc:
        # In case reinitialization fails we provide a clear error
        raise RuntimeError("Failed to reinitialize histogram bins") from exc

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    Parameters
    ----------
    separator : str, optional
        Delimiter for values. Defaults to comma.
    header : str, optional
        First line of the output. If supplied, a newline is appended
        after it automatically.

    Returns
    -------
    str
        CSV representation of the graph.

    Notes
    -----
    The graph is expected to contain points in one of three clear
    formats: a ``points`` dictionary mapping coordinates to values,
    a dictionary via ``items()``, or an iterable yielding
    ``(coordinate, value)`` tuples.  If none of these are found a
    ``ValueError`` is raised.  Coordinated and values are coerced to
    strings using ``repr``-like conversion; iterables are flattened
    one level each.  The method is tolerant of missing or invalid
    data, skipping over items that cannot be unpacked.
    """
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")

    lines = []
    if header is not None:
        lines.append(str(header))

    # Resolve source of graph data
    try:
        data_iter = self.points.items()
    except AttributeError:
        try:
            data_iter = self.items()
        except AttributeError:
            if hasattr(self, "__iter__"):
                data_iter = iter(self)
            else:
                raise ValueError("Graph has no recognizable data source")

    for item in data_iter:
        # item should be a (coord, value) pair
        if isinstance(item, tuple) and len(item) == 2:
            coord, value = item
        else:
            # item not a pair; skip this entry
            continue

        # Handle coordinate, which may be a scalar or iterable
        if isinstance(coord, (str, bytes)):
            coord_parts = [coord]
        else:
            try:
                coord_parts = list(coord)
            except TypeError:
                coord_parts = [coord]
        coord_strs = [str(c) for c in coord_parts]

        # Handle value, also iterable or scalar
        if isinstance(value, (str, bytes)):
            value_parts = [value]
        else:
            try:
                value_parts = list(value)
            except TypeError:
                value_parts = [value]
        value_strs = [str(v) for v in value_parts]

        lines.append(separator.join(coord_strs + value_strs))

    return "\n".join(lines)

def _get_err_indices(self, coord_name):
        """Get error indices corresponding to a coordinate."""
        # Validate inputs
        if not isinstance(coord_name, str):
            raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")

        # Ensure the error data structure exists
        if not hasattr(self, "_err") or self._err is None:
            raise AttributeError("The instance has no error data (_err attribute).")

        # Attempt to get the error array for the specified coordinate
        try:
            err_data = self._err[coord_name] if isinstance(self._err, dict) else getattr(self, f"_err_{coord_name}", None)
        except (KeyError, AttributeError):
            err_data = None

        if err_data is None:
            raise ValueError(f"No error data found for coordinate '{coord_name}'.")

        # If err_data is not a NumPy array, try to convert it
        try:
            import numpy as np
        except Exception as exc:
            raise ImportError("NumPy must be available for error index computation.") from exc

        try:
            err_array = np.asarray(err_data)
        except Exception:
            raise TypeError(f"Error data for coordinate '{coord_name}' cannot be converted to a NumPy array.")

        # Determine indices where the error is non‑zero (or non‑nan if boolean array is provided)
        if err_array.dtype == bool:
            idx = np.where(err_array)[0]
        else:
            # Treat zeros and NaNs as 'no error'
            idx = np.where((err_array != 0) & ~np.isnan(err_array))[0]

        # Ensure the indices are of integer type and sorted
        return np.sort(idx.astype(np.int64)) if idx.size else np.array([], dtype=np.int64)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Check if the object itself is a FillRequest
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # FillRequest class is not defined, cannot check directly
        pass

    # Avoid treating a Source sequence as a valid FillRequest sequence
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # Source class is not defined, skip this check
        pass

    # Attempt to iterate over seq and look for any FillRequest elements
    try:
        for item in seq:
            try:
                if isinstance(item, FillRequest):
                    return True
            except NameError:
                # If FillRequest is undefined, break out
                break
    except TypeError:
        # seq is not iterable
        return False
    except Exception:
        # Catch all unexpected errors to avoid failing silently
        return False

    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return (
            hasattr(obj, "fill")
            and callable(getattr(obj, "fill"))
            and hasattr(obj, "request")
            and callable(getattr(obj, "request"))
        )
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    if obj is None:
        return False
    try:
        attr = getattr(obj, 'run')
        return callable(attr)
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """

    def _deep_copy_dict(src):
        """Create a deep copy of a dictionary."""
        result = {}
        for k, v in src.items():
            if isinstance(v, dict):
                result[k] = _deep_copy_dict(v)
            else:
                result[k] = v
        return result

    def _diff(sub1, sub2, lvl):
        result = {}
        for key, val1 in sub1.items():
            if key not in sub2:
                # Key missing in d2: copy entire value
                if isinstance(val1, dict):
                    result[key] = _deep_copy_dict(val1)
                else:
                    result[key] = val1
            else:
                val2 = sub2[key]
                if val1 == val2:
                    continue  # identical, no difference
                # Values differ
                if isinstance(val1, dict) and isinstance(val2, dict):
                    if lvl == -1 or lvl > 1:
                        # Recursively compute difference
                        next_lvl = -1 if lvl == -1 else lvl - 1
                        sub_diff = _diff(val1, val2, next_lvl)
                        if sub_diff:
                            result[key] = sub_diff
                    else:  # lvl == 1 or 0
                        # Do not recurse; include whole value from d1
                        result[key] = _deep_copy_dict(val1)
                else:
                    # At least one value is not a dict: include val1
                    result[key] = val1
        return result

    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")
    return _diff(d1, d2, level)

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Import numpy lazily to avoid required dependency at class import time
    try:
        import numpy as np
    except Exception as exc:
        raise RuntimeError("numpy is required for histogram operations") from exc

    # Validate and coerce coord to a 1‑D numeric array
    try:
        coord_arr = np.asarray(coord, dtype=float)
    except Exception as exc:
        raise ValueError(f"coord must be convertible to a numeric array, got {coord!r}") from exc

    if coord_arr.ndim != 1:
        raise ValueError(f"coord must be one‑dimensional, got array with shape {coord_arr.shape}")

    # Ensure the histogram has the necessary storage attributes
    if not hasattr(self, "edges") or not hasattr(self, "bins"):
        raise AttributeError("Histogram object must have 'edges' and 'bins' attributes")

    edges = self.edges
    if len(coord_arr) != len(edges):
        raise ValueError(f"coord dimension {len(coord_arr)} does not match histogram dimensionality {len(edges)}")

    # Validate weight (force scalar numeric)
    try:
        weight_val = float(weight)
    except Exception as exc:
        raise ValueError(f"weight must be a scalar numeric value, got {weight!r}") from exc

    # Find bin indices for each coordinate dimension
    bin_indices = []
    for dim, edge in enumerate(edges):
        # The interval for each bin is [edge[i], edge[i+1])
        # Use np.searchsorted with side='right' and subtract one to get the index
        idx = np.searchsorted(edge, coord_arr[dim], side="right") - 1
        # Out‑of‑range handling: ignore if outside histogram boundaries
        if idx < 0 or idx >= len(edge) - 1:
            return  # ignore outside boundaries
        bin_indices.append(idx)

    # Use tuple indexing for potentially multidimensional bins array
    try:
        self.bins[tuple(bin_indices)] += weight_val
    except Exception as exc:
        raise RuntimeError("Failed to update histogram bins; ensure 'bins' is a mutable array") from exc

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    import re

    # Define allowed patterns for keys and values.
    # These are common Kubernetes/OpenTelemetry/Prometheus label naming conventions.
    key_pattern = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_\-]{0,63}$')
    value_pattern = re.compile(r'^[a-zA-Z0-9_\-]{0,63}$')

    errors = []

    for key, value in labels.items():
        # ---- Validate key ----
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            try:
                key_str = key.decode() if isinstance(key, bytes) else key
            except Exception:
                errors.append({str(key): 'expected string or bytes-like object'})
                key_str = str(key)
            if not key_pattern.match(key_str):
                errors.append({key_str: f"Label key '{key_str}' does not match the regex '{key_pattern.pattern}'"})

        # ---- Validate value ----
        # Handle list/tuple values (e.g. array of strings)
        if isinstance(value, (list, tuple)):
            for item in value:
                if not isinstance(item, (str, bytes)):
                    errors.append({str(item): 'expected string or bytes-like object'})
                else:
                    try:
                        item_str = item.decode() if isinstance(item, bytes) else item
                    except Exception:
                        errors.append({str(item): 'expected string or bytes-like object'})
                        item_str = str(item)
                    if not value_pattern.match(item_str):
                        errors.append({item_str: f"Label value '{item_str}' does not match the regex '{value_pattern.pattern}'"})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                try:
                    value_str = value.decode() if isinstance(value, bytes) else value
                except Exception:
                    errors.append({str(value): 'expected string or bytes-like object'})
                    value_str = str(value)
                if not value_pattern.match(value_str):
                    errors.append({value_str: f"Label value '{value_str}' does not match the regex '{value_pattern.pattern}'"})

    if errors:
        # Assuming ValidationError is defined elsewhere in the caller's context.
        raise ValidationError(messages=errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a partial observer_schema dictionary from a Kubernetes resource dictionary.

    Args:
        manifest_dict (dict): Partial Kubernetes resources.
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer_schema of a Kubernetes resource.

    Returns:
        dict: Generated partial observer_schema, with non-list and non-dict values replaced by None.
    """
    if not isinstance(manifest_dict, dict):
        # If the provided value is not a dict, there's nothing to process.
        return None

    def _process_list(lst):
        """Helper that processes a list similarly to the main function."""
        if not isinstance(lst, list):
            return None
        processed = []
        for item in lst:
            if isinstance(item, dict):
                processed.append(generate_default_observer_schema_dict(item, first_level=False))
            elif isinstance(item, list):
                processed.append(_process_list(item))
            else:
                processed.append(None)
        return processed

    result = {}
    for key, value in manifest_dict.items():
        # Preserve top-level identifying fields if requested.
        if first_level and key in {"apiVersion", "kind", "metadata"}:
            result[key] = value
            continue

        if isinstance(value, dict):
            # Recurse into nested dictionaries.
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Process lists specially.
            result[key] = _process_list(value)
        else:
            # Replace primitive values with None.
            result[key] = None

    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    last_applied_manifest if they are not yet present.

    Returns
    -------
    list
        Updated last_applied_manifest list.
    """
    # Basic type validation
    if last_applied_manifest is None:
        last_applied_manifest = []
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    # If observer_schema is not a list or is empty, simply copy response values
    if not isinstance(observer_schema, list) or not observer_schema:
        return response.copy()

    # Use the first schema element as a template for new items, if available
    schema_template = observer_schema[0] if len(observer_schema) > 0 else None

    # Resolve a single element update helper (assumes existence)
    try:
        from __main__ import update_last_applied_manifest_dict_from_resp
    except Exception:
        # If helper not available, fall back to shallow copy
        def update_last_applied_manifest_dict_from_resp(_, __, ___):
            return

    for idx, resp_item in enumerate(response):
        # Skip None items in the response
        if resp_item is None:
            continue

        # Ensure the target list has enough entries
        if idx >= len(last_applied_manifest):
            # Initialize a new entry based on schema template or using an empty dict
            new_entry = {}
            if isinstance(schema_template, dict):
                # Attempt to clone the structure from the schema template
                if 'object' in schema_template:
                    new_entry = {}
                elif 'list' in schema_template:
                    new_entry = []
            last_applied_manifest.append(new_entry)

        # Update the existing entry recursively
        try:
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[idx], observer_schema, resp_item
            )
        except Exception:
            # Fall back to a direct overwrite if recursive update fails
            last_applied_manifest[idx] = resp_item

    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_list_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``; each key maps to
            a mapping describing the field.  The mapping may contain:
            * ``type``: ``dict``, ``list``, or omitted for a scalar value.
            * ``schema``: nested observer schema for sub‑objects.
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If an observed field is not present in ``response``.
    """
    # Guard against ``response`` not being a mapping
    if not isinstance(response, dict):
        raise KeyError("Response must be a mapping")

    for field, field_schema in observer_schema.items():
        # Validate that the field exists in the response
        if field not in response:
            raise KeyError(
                f"Observed field '{field}' missing from Kubernetes response"
            )

        # Grab the schema details; allow schema to be ``None`` or a dict
        schema_type = None
        schema_nested = None
        if isinstance(field_schema, dict):
            schema_type = field_schema.get("type")
            schema_nested = field_schema.get("schema")

        # If the field is missing in the applied manifest, initialise it
        if field not in last_applied_manifest:
            if schema_type == "dict" and isinstance(
                response[field], dict
            ):
                # Initialise nested dict and recurse
                last_applied_manifest[field] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], schema_nested or {}, response[field]
                )
            elif schema_type == "list" and isinstance(
                response[field], list
            ):
                # Initialise list; elements may be scalars or dicts
                last_applied_manifest[field] = []
                child_schema = schema_nested
                for item in response[field]:
                    if isinstance(item, dict) and child_schema:
                        new_item = {}
                        update_last_applied_manifest_dict_from_resp(
                            new_item, child_schema, item
                        )
                        last_applied_manifest[field].append(new_item)
                    else:
                        last_applied_manifest[field].append(item)
            else:
                # Scalar or unsupported nested structure: copy value
                last_applied_manifest[field] = response[field]
        else:
            # Field already present: we may need to merge nested sub‑fields
            existing_value = last_applied_manifest[field]
            resp_value = response[field]
            if isinstance(existing_value, dict) and isinstance(resp_value, dict):
                # Recursively merge missing nested dict fields
                update_last_applied_manifest_dict_from_resp(
                    existing_value, schema_nested or {}, resp_value
                )
            elif (
                isinstance(existing_value, list)
                and isinstance(resp_value, list)
                and schema_type == "list"
                and schema_nested
            ):
                # Merge list of dicts: iterate over common indices
                child_schema = schema_nested
                for i, (elem_last, elem_resp) in enumerate(
                    zip(existing_value, resp_value)
                ):
                    if isinstance(elem_resp, dict):
                        update_last_applied_manifest_dict_from_resp(
                            elem_last, child_schema, elem_resp
                        )
            # Scalars remain unchanged

    # No explicit return; the function mutates ``last_applied_manifest`` in place.

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate the application object and manifest
    if not hasattr(app, "spec"):
        raise ValueError("Application object has no 'spec' attribute")
    if not hasattr(app.spec, "manifest"):
        raise ValueError("Application spec has no 'manifest' attribute")

    manifest = app.spec.manifest
    if not isinstance(manifest, dict):
        raise TypeError("Application spec.manifest must be a dict")

    # Existing observer schemas, if any
    observer_schema = getattr(app.spec, "observer_schema", {})
    if observer_schema is None:
        observer_schema = {}
    if not isinstance(observer_schema, dict):
        raise TypeError("Application spec.observer_schema must be a dict")

    # Define a minimal default schema. Adjust this definition to match the real schema definition if known.
    default_schema = {"observed": True}

    # Generate defaults for each resource without a custom schema
    for resource_name in manifest.keys():
        if resource_name not in observer_schema:
            observer_schema[resource_name] = default_schema

    # Assign the updated schema back to the application spec
    app.spec.observer_schema = observer_schema

    return observer_schema

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        p = Path(path)
    except Exception:
        # Invalid path input
        return False

    # Path must exist
    if not p.exists():
        return False

    # We only support directories as potential roots
    if p.is_file():
        return False

    # Determine candidate root: current path or its parent
    candidates = [p, p.parent]
    root = None
    for cand in candidates:
        if (cand / "manifest.v1.json").is_file() and (cand / "objects").is_dir():
            root = cand
            break

    if not root:
        return False

    try:
        # Basic root checks
        if not (root / "manifest.v1.json").is_file():
            return False
        objects_dir = root / "objects"
        if not objects_dir.is_dir():
            return False

        # Iterate over object directories
        for obj in objects_dir.iterdir():
            if not obj.is_dir():
                continue  # Skip non-directories, not an error

            # Each object must have a manifest
            if not (obj / "manifest.v1.json").is_file():
                return False

            versions_dir = obj / "versions"
            if not versions_dir.is_dir():
                return False

            # Ensure at least one version exists
            if not any(v.is_dir() for v in versions_dir.iterdir()):
                return False

            # Check minimal structure within each version
            for ver in versions_dir.iterdir():
                if not ver.is_dir():
                    continue  # Skip: not an error

                # Optional: check for a manifest file per version
                # (not mandatory for this simple validation)
                if not (ver / "manifest").is_file():
                    pass  # warning: not required for validation

                # Optional: blobs and ui directories may exist
                # They are not required for basic validity
                # but if present, ensure they are directories
                if (ver / "blobs").exists() and not (ver / "blobs").is_dir():
                    return False
                if (ver / "ui").exists() and not (ver / "ui").is_dir():
                    return False

        # All checks passed
        return True

    except Exception:
        # Any unexpected error results in invalid
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    try:
        errors = getattr(self, "errors", None)
        if errors is None:
            return f"{prefix}Status unknown"
        if not hasattr(errors, "__len__"):
            return f"{prefix}Status unknown"
        if len(errors) == 0:
            return f"{prefix}OK"
        return f"{prefix}{len(errors)} error(s)"
    except Exception as exc:
        return f"{prefix}Error: {exc}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Attempt to locate the log attribute
    log = None
    for name in ('validation_log', 'log', 'status_log', 'history'):
        if hasattr(self, name):
            log = getattr(self, name)
            break

    # If no log is found, return an empty string
    if log is None:
        return ''

    # Convert the log to a list of string lines
    try:
        if isinstance(log, str):
            lines = log.splitlines()
        elif isinstance(log, (list, tuple)):
            lines = [str(item) for item in log]
        else:
            # Try to iterate over the log if it's an iterable container
            try:
                it = iter(log)
                # Avoid treating a string as an iterable of chars
                if isinstance(log, str):
                    lines = log.splitlines()
                else:
                    lines = [str(item) for item in it]
            except TypeError:
                # Fallback to a single string representation
                lines = [str(log)]
    except Exception:
        lines = [str(log)]

    # Apply optional prefix to each line
    if prefix:
        prefixed_lines = [f"{prefix}{line}" for line in lines]
    else:
        prefixed_lines = lines

    return "\n".join(prefixed_lines)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check that every digest listed in ``manifest_files`` is also used, and that
    every digest reported as used exists in the manifest. ``manifest_files`` is
    expected to be a mapping from digest name (string) to an iterable of file
    paths. ``digests_used`` may be a set, list, or mapping of the same digest
    names. The method raises :class:`TypeError` for invalid input types and
    :class:`ValueError` if any digest is missing or unused. It returns ``True``
    if all checks pass.
    """
    # Validate manifest_files
    if not isinstance(manifest_files, dict):
        raise TypeError(
            f"manifest_files should be a dict, got {type(manifest_files)!r}"
        )
    # Validate digests_used
    if isinstance(digests_used, dict):
        used_digest_names = set(digests_used.keys())
    elif isinstance(digests_used, (set, list, tuple)):
        used_digest_names = set(digests_used)
    else:
        raise TypeError(
            f"digests_used should be a set, list, tuple or dict, got {type(digests_used)!r}"
        )

    # Ensure every digest in manifest is used
    for digest_name, file_iterable in manifest_files.items():
        if not isinstance(digest_name, str):
            raise TypeError(
                f"Digest names must be strings, got {type(digest_name)!r}"
            )
        if not hasattr(file_iterable, "__iter__"):
            raise TypeError(
                f"Files for digest '{digest_name}' must be an iterable, got {type(file_iterable)!r}"
            )
        # Skip check if the digest is somehow not expected to be used (e.g. empty list)
        if ", ".join(map(str, file_iterable)) == "":
            continue
        if digest_name not in used_digest_names:
            raise ValueError(
                f"Digest '{digest_name}' appears in the manifest but is not reported as used."
            )

    # Ensure every used digest actually exists in the manifest
    for used_digest in used_digest_names:
        if used_digest not in manifest_files:
            raise ValueError(
                f"Digest '{used_digest}' is reported as used but does not exist in the manifest."
            )

    return True

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if prior is None:
            raise ValueError("prior cannot be None")
        # Ensure the object type
        try:
            import inspect
            if not inspect.isclass(prior.__class__):
                raise TypeError
        except Exception:
            # If InventoryValidator is not imported, defer to isinstance check
            pass
        if not isinstance(prior, InventoryValidator):
            raise TypeError(f"prior must be an InventoryValidator instance, got {type(prior).__name__}")

        # Helper to fetch an attribute safely
        def _get_attr(obj, *attrs):
            for name in attrs:
                if hasattr(obj, name):
                    return getattr(obj, name)
            return None

        # Check that both represent the same inventory entity
        self_id = _get_attr(self, "inventory_id", "id", "name")
        prior_id = _get_attr(prior, "inventory_id", "id", "name")
        if self_id is None or prior_id is None:
            raise ValueError("Unable to determine inventory identifiers on one or both objects.")
        if self_id != prior_id:
            raise ValueError(f"Inventory identity mismatch: self={self_id}, prior={prior_id}")

        # Retrieve the version values
        self_version = _get_attr(self, "version", "revision", "version_number")
        prior_version = _get_attr(prior, "version", "revision", "version_number")
        if self_version is None or prior_version is None:
            raise ValueError("Unable to determine version for one or both inventory objects.")

        # Compare versions: the prior must be older (smaller) than self
        try:
            # Try numeric comparison first
            self_num = float(self_version)
            prior_num = float(prior_version)
            comparator = lambda a, b: a > b
        except Exception:
            # Fallback to lexicographic
            self_num = self_version
            prior_num = prior_version
            comparator = lambda a, b: a > b

        if not comparator(self_num, prior_num):
            raise ValueError(
                f"Prior version ({prior_version}) is not earlier than current version ({self_version})."
            )

        # All checks passed
        return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and make sure that only files
    listed in the manifest are referenced.
    """
    try:
        # Basic type checks
        if fixity is None:
            # No fixity block to validate – consider it valid
            return True
        if not isinstance(fixity, dict):
            raise TypeError("fixity must be a dict")

        if manifest_files is None:
            raise TypeError("manifest_files must be provided")
        if not isinstance(manifest_files, (set, list, tuple)):
            # Attempt to convert iterable to set for membership tests
            try:
                manifest_set = set(manifest_files)
            except Exception as exc:
                raise TypeError("manifest_files must be an iterable of file names") from exc
        else:
            manifest_set = set(manifest_files)

        # Validate each entry in the fixity block
        for file_path, checks in fixity.items():
            if file_path not in manifest_set:
                raise ValueError(f"Fixity references unknown file '{file_path}' not present in manifest")
            if not isinstance(checks, dict):
                raise ValueError(f"Fixity entry for '{file_path}' must be a dict mapping checksum algorithms to values")
            if not checks:
                raise ValueError(f"Fixity entry for '{file_path}' is empty; at least one checksum is required")
            for algo, value in checks.items():
                if not isinstance(algo, str) or not isinstance(value, str):
                    raise ValueError(
                        f"Checksum algorithm and value must be strings for file '{file_path}': got algo={algo!r}, value={value!r}"
                    )

        # All checks passed
        return True

    except (TypeError, ValueError) as exc:
        # Re‑raise validation errors to callers
        raise
    except Exception as exc:
        # Wrap unexpected exceptions in a RuntimeError to preserve the stack trace
        raise RuntimeError(f"Error while validating fixity block: {exc}") from exc

def files_list(path):
    """
    Return the files in `path`
    """
    # Use __import__ to avoid a top‑level import statement
    os = __import__("os")

    # Validate input type
    if not isinstance(path, (str, os.PathLike)):
        raise TypeError(f"`path` must be a string or PathLike object, got {type(path).__name__}")

    # Resolve the path to a string if it's PathLike
    try:
        path_str = os.fspath(path)
    except Exception as e:
        raise TypeError(f"Unable to convert `path` to a path string: {e}") from e

    # Check existence
    if not os.path.exists(path_str):
        raise FileNotFoundError(f"The specified path does not exist: {path_str}")

    # Must be a directory
    if not os.path.isdir(path_str):
        raise NotADirectoryError(f"Specified path is not a directory: {path_str}")

    try:
        # List entries, filter to files only
        files = [
            entry
            for entry in os.listdir(path_str)
            if os.path.isfile(os.path.join(path_str, entry))
        ]
        # Return sorted list for consistency
        return sorted(files)
    except OSError as exc:
        # Wrap low‑level OS errors into a more general exception
        raise RuntimeError(f"Error reading directory '{path_str}': {exc}") from exc

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError("The 'folder' argument must be a string representing a path.")
    if not os.path.isdir(folder):
        raise NotADirectoryError(f"The specified path does not exist or is not a directory: {folder}")

    grouped = {}
    try:
        for entry in os.listdir(folder):
            path = os.path.join(folder, entry)
            if not os.path.isfile(path):
                continue  # skip non-file entries
            base, ext = os.path.splitext(entry)
            grouped.setdefault(base, []).append(entry)
    except OSError as exc:
        raise RuntimeError(f"Error accessing files in '{folder}': {exc}") from exc

    # Filter only basenames that have at least one XML file
    result = {base: files for base, files in grouped.items() if any(os.path.splitext(f)[1].lower() == ".xml" for f in files)}
    return result

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    try:
        if not isinstance(content, str):
            raise TypeError("content must be a string")
        return content.replace('w:st="', 'w-st="')
    except Exception as exc:
        raise ValueError(f"Error processing content: {exc}") from exc

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate indent
    if not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non‑negative integer")

    def _pretty_obj(obj, cur_indent, is_root=False):
        indent_str = " " * cur_indent
        # Simple atomic types
        if isinstance(obj, (str, bytes, int, float, bool, type(None))):
            result = f"{indent_str}{repr(obj)}"
        # Avoid recursive call to self.pretty (infinite loop)
        elif hasattr(obj, "pretty") and obj.__class__ is not type(self):
            try:
                result = obj.pretty(cur_indent, debug=debug)
            except Exception:
                result = f"{indent_str}{repr(obj)}"
        # Dictionaries
        elif isinstance(obj, dict):
            lines = [f"{indent_str}{{"]
            for k, v in obj.items():
                val_str = _pretty_obj(v, cur_indent + 4)
                lines.append(f"{indent_str}    {repr(k)}: {val_str.strip()}")
            lines.append(f"{indent_str}}}")
            result = "\n".join(lines)
        # Sequences and sets
        elif isinstance(obj, (list, tuple, set)):
            if isinstance(obj, list):
                open_sym, close_sym = "[", "]"
            elif isinstance(obj, tuple):
                open_sym, close_sym = "(", ")"
            else:
                open_sym, close_sym = "{", "}"
            lines = [f"{indent_str}{open_sym}"]
            for item in obj:
                lines.append(_pretty_obj(item, cur_indent + 4))
            lines.append(f"{indent_str}{close_sym}")
            result = "\n".join(lines)
        # Objects with attributes
        elif hasattr(obj, "__dict__"):
            cls_name = obj.__class__.__name__
            lines = [f"{indent_str}{cls_name}("]
            attrs = sorted(vars(obj).items())
            for k, v in attrs:
                val_str = _pretty_obj(v, cur_indent + 4)
                lines.append(f"{indent_str}    {k}={val_str.strip()}")
            lines.append(f"{indent_str})")
            result = "\n".join(lines)
        else:
            result = f"{indent_str}{repr(obj)}"

        # Add debug header for the top‑level call
        if is_root and debug:
            header = f"{indent_str}DEBUG: {obj.__class__.__name__} object id {hex(id(obj))}"
            return header + "\n" + result
        return result

    return _pretty_obj(self, indent, is_root=True)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # We will maintain a working copy of the argument list and attempt to
    # collapse expressions according to the rules above.  If we cannot
    # determine the expression type or its structure we simply return the
    # original list unchanged.
    try:
        new_args = list(args)
        for i, expr in enumerate(new_args):
            # Skip if the expression is not an And or Or
            # (commonly represented with .is_And / .is_Or attributes).
            # If those attributes do not exist, silently continue.
            is_and = getattr(expr, "is_And", False)
            is_or = getattr(expr, "is_Or", False)
            if not (is_and or is_or):
                continue

            # Extract arguments of binary operators if possible.
            subexprs = getattr(expr, "args", None)
            if not subexprs or len(subexprs) != 2:
                # Skip non-binary construction – we don't handle arity >2
                continue

            a, b = subexprs

            # Helper functions for checking equality with the other subexpression.
            # We compare expressions directly as objects since they may be
            # instances of custom expression classes.
            def contains(expr_container, target):
                """Return True if target is among the args of expr_container."""
                try:
                    if not getattr(expr_container, "args", None):
                        return False
                    return target in expr_container.args
                except Exception:
                    return False

            # --- Absorption rules for & (AND) with | (OR) ---
            if is_and:
                # A & (A | B) -> A
                if getattr(a, "is_Or", False) and contains(a, b):
                    # a is Or(b, B)
                    new_args[i] = b
                    continue
                if getattr(b, "is_Or", False) and contains(b, a):
                    new_args[i] = a
                    continue

                # Negative absorption for AND:
                # A & (~A | B) -> A & B
                if getattr(a, "is_Or", False):
                    try:
                        first = a.args[0]
                        if getattr(first, "is_Not", False) and first.args[0] is b:
                            # a = Or(Not(b), B1)
                            B1 = a.args[1] if a.args[0] is b else a.args[0]
                            new_args[i] = getattr(type(a), "func", lambda *x: None)(b, B1)
                            continue
                    except Exception:
                        pass
                if getattr(b, "is_Or", False):
                    try:
                        first = b.args[0]
                        if getattr(first, "is_Not", False) and first.args[0] is a:
                            B1 = b.args[1] if b.args[0] is a else b.args[0]
                            new_args[i] = getattr(type(b), "func", lambda *x: None)(a, B1)
                            continue
                    except Exception:
                        pass

            # --- Absorption rules for | (OR) with & (AND) ---
            if is_or:
                # A | (A & B) -> A
                if getattr(a, "is_And", False) and contains(a, b):
                    new_args[i] = b
                    continue
                if getattr(b, "is_And", False) and contains(b, a):
                    new_args[i] = a
                    continue

                # Negative absorption for OR:
                # A | (~A & B) -> A | B
                if getattr(a, "is_And", False):
                    try:
                        first = a.args[0]
                        if getattr(first, "is_Not", False) and first.args[0] is b:
                            B1 = a.args[1] if a.args[0] is b else a.args[0]
                            new_args[i] = getattr(type(a), "func", lambda *x: None)(b, B1)
                            continue
                    except Exception:
                        pass
                if getattr(b, "is_And", False):
                    try:
                        first = b.args[0]
                        if getattr(first, "is_Not", False) and first.args[0] is a:
                            B1 = b.args[1] if b.args[0] is a else b.args[0]
                            new_args[i] = getattr(type(b), "func", lambda *x: None)(a, B1)
                            continue
                    except Exception:
                        pass

        # Remove duplicate expressions that might arise after absorption.
        # Preserve the original order of first occurrences.
        seen = set()
        result = []
        for expr in new_args:
            try:
                # expressions should be hashable; if not, use id
                key = expr
            except Exception:
                key = id(expr)
            if key not in seen:
                seen.add(key)
                result.append(expr)
        return result

    except Exception:
        # In case the structure of expressions is unknown or does not
        # fit the expected pattern, fall back to returning the input
        # unchanged to avoid silent failures.
        return list(args)

# Validate input types and constraints
    if not isinstance(user, str) or not user.strip():
        raise ValueError(f"'user' must be a non-empty string, got {user!r}")
    if not isinstance(etcd_host, str) or not etcd_host.strip():
        raise ValueError(f"'etcd_host' must be a non-empty string, got {etcd_host!r}")
    if not isinstance(etcd_port, int) or etcd_port <= 0:
        raise ValueError(f"'etcd_port' must be a positive integer, got {etcd_port!r}")

    # Build the configuration dictionary
    config = {
        "user": user,
        "etcd": {
            "host": etcd_host,
            "port": etcd_port
        }
    }

    return config

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        result = namefunc()
    except Exception as exc:
        raise RuntimeError("namefunc raised an exception") from exc
    # Detect Python 2 by the presence of the builtin 'unicode'
    if 'unicode' in globals():
        # In Python 2, convert any unicode string to a UTF‑8 encoded bytestring
        try:
            if isinstance(result, unicode):
                return result.encode('utf-8')
        except NameError:
            # Just in case 'unicode' is not available for some reason
            pass
    return result

def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to use importlib.metadata (Python 3.8+). Fall back to importlib_metadata backport if needed.
    try:
        try:
            from importlib.metadata import version as _vers, PackageNotFoundError
        except ImportError:  # pragma: no cover
            from importlib_metadata import version as _vers, PackageNotFoundError
        # Candidate package names
        pkg_name = __package__
        # Even though __package__ might be None when run as a script,
        # try it anyway and ignore failure.
        if pkg_name:
            try:
                return _vers(pkg_name)
            except PackageNotFoundError:
                pass
        # Also try the module name (which could be the distribution name).
        if __name__ and __name__ != "__main__":
            try:
                return _vers(__name__)
            except PackageNotFoundError:
                pass
    except Exception:  # pragma: no cover
        pass

    # Try pkg_resources as a secondary fallback.
    try:
        import pkg_resources
        dist_name = __package__ or __name__
        for dist in pkg_resources.working_set:
            if dist.project_name.lower() == dist_name.lower():
                return dist.version
    except Exception:  # pragma: no cover
        pass

    # Attempt to read a __version__ attribute from the current module.
    try:
        mod = __import__(__name__)
        if hasattr(mod, "__version__"):
            return getattr(mod, "__version__")
    except Exception:  # pragma: no cover
        pass

    # Default fallback value in case everything else fails.
    return "0.0.0"

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        # Default: no plus sign found
        has_plus = False
        for p in pieces:
            # If the element is a string, check for '+' inside it
            if isinstance(p, str) and '+' in p:
                has_plus = True
                break
            # If the element is exactly the character '+'
            if p == '+':
                has_plus = True
                break
        return '.' if has_plus else '+'
    except Exception:
        # In case pieces is not iterable or any other error occurs,
        # fall back to returning '+'
        return '+'

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    # Ensure a registry exists
    if "_VCS_HANDLERS" not in globals():
        globals()["_VCS_HANDLERS"] = {}
    registry = globals()["_VCS_HANDLERS"]
    # Validate inputs
    try:
        if not isinstance(vcs, str):
            raise TypeError("vcs must be a string")
        if not callable(method):
            raise TypeError("method must be a callable")
        # Register the handler
        registry[vcs] = method
        return method
    except Exception as exc:
        raise RuntimeError(f"Failed to register VCS handler for '{vcs}': {exc}") from exc

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """
        Validate storage root hierarchy.

        The method traverses the storage hierarchy stored in `self.storage_root`
        (expected to be a mapping of identifiers to objects).  For each object the
        following checks are optionally performed:

        * If ``validate_objects`` is True, the object is expected to have a
          ``validate()`` method that returns ``True`` when the object is
          internally consistent, and raises an exception otherwise.
        * If ``check_digests`` is True, the object should expose a ``digest``
          attribute and a ``compute_digest()`` method.  The stored digest is
          compared with the freshly computed one.

        Any warning about a failed check is emitted via the :mod:`warnings` module
        if ``show_warnings`` is True; otherwise the warning is silently suppressed.

        Returns:
            tuple[int, int]: ``num_objects`` – the total number of objects
            inspected; ``good_objects`` – the number of objects that passed
            all requested checks.
        """
        import warnings

        # Ensure we have a crawlable structure; fall back to empty mapping if not.
        objects = getattr(self, "storage_root", {})
        if objects is None:
            objects = {}

        num_objects = 0
        good_objects = 0

        for key, obj in objects.items():
            num_objects += 1
            ok = True

            # Object-level validation
            if validate_objects:
                try:
                    # Prefer a validate() method; otherwise skip
                    if hasattr(obj, "validate"):
                        ok = ok and bool(obj.validate())
                except Exception as exc:
                    ok = False
                    if show_warnings:
                        warnings.warn(f"Validation failed for object {key}: {exc}")

            # Digest comparison
            if check_digests and ok:
                try:
                    if hasattr(obj, "digest") and hasattr(obj, "compute_digest"):
                        expected = getattr(obj, "digest")
                        actual = obj.compute_digest()
                        if expected != actual:
                            ok = False
                            if show_warnings:
                                warnings.warn(
                                    f"Digest mismatch for object {key}: "
                                    f"expected {expected}, got {actual}"
                                )
                except Exception as exc:
                    ok = False
                    if show_warnings:
                        warnings.warn(f"Digest check failed for object {key}: {exc}")

            if ok:
                good_objects += 1

        return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    :param version_dirs: List of version directory names in ascending order.
    :return: Dictionary mapping content paths to lists of mismatches.
    :raises FileNotFoundError: If an expected inventory file is missing.
    :raises ValueError: If inputs are malformed.
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    # Validate the input list
    if not isinstance(version_dirs, list):
        raise TypeError("version_dirs must be a list of directory names")

    # Ensure we have a root inventory for comparison
    root_inventory = getattr(self, "root_inventory", {})
    if not isinstance(root_inventory, dict):
        raise ValueError("root_inventory attribute must be a dict")

    # Store mismatched digests
    mismatches = {}

    # Helper to load an inventory file
    def _load_inventory(dir_path):
        # Try YAML first, then JSON
        for suffix in (".yaml", ".yml", ".json"):
            inv_file = os.path.join(dir_path, "inventory" + suffix)
            if os.path.isfile(inv_file):
                try:
                    with open(inv_file, "r", encoding="utf-8") as f:
                        if suffix in (".yaml", ".yml"):
                            if yaml is None:
                                raise RuntimeError("PyYAML is not available")
                            data = yaml.safe_load(f)
                        else:
                            data = json.load(f)
                    if not isinstance(data, dict):
                        raise ValueError(f"Inventory file {inv_file} must contain a mapping")
                    return data
                except Exception as exc:
                    raise RuntimeError(f"Failed to read inventory {inv_file}: {exc}")
        raise FileNotFoundError(f"Missing inventory file for directory {dir_path}")

    # Process each version directory
    for v_dir in version_dirs:
        if not v_dir:
            continue
        try:
            inventory = _load_inventory(v_dir)
        except Exception as exc:
            raise FileNotFoundError(f"Error loading inventory for {v_dir}: {exc}")

        # Compare each digest with the root inventory
        for path, entry in inventory.items():
            # The entry can be a dict containing 'digest' key or a raw digest string
            digest = entry.get("digest") if isinstance(entry, dict) else entry
            if not digest:
                continue
            root_digest = root_inventory.get(path)
            if root_digest is not None and root_digest != digest:
                mismatches.setdefault(path, []).append(
                    {
                        "version": v_dir,
                        "inventory_digest": digest,
                        "root_digest": root_digest,
                    }
                )

    # Store mismatches for later use and return them
    self.inventory_differences = mismatches
    return mismatches

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Use dynamic imports to avoid top‑level import statements
    try:
        os = __import__('os')
        re = __import__('re')
    except Exception
    def _error(msg):
        return f'error: {msg}'
    # Validate input type
    if not isinstance(path, str):
        return _error('input is not a string')
    try:
        abs_path = os.path.abspath(os.path.expanduser(path))
    except Exception as e:
        return _error(f'cannot resolve path: {e}')
    if not os.path.exists(abs_path):
        return _error('path does not exist')
    # Check if path is a directory
    if os.path.isdir(abs_path):
        # Root: presence of .ocfl_root file
        if os.path.isfile(os.path.join(abs_path, '.ocfl_root')):
            return 'root'
        # Object: look for subdirectory matching "0=*"
        try:
            for entry in os.listdir(abs_path):
                full = os.path.join(abs_path, entry)
                if os.path.isdir(full) and re.match(r'^[0-9]+=.*$', entry):
                    return 'object'
        except Exception:
            # If listing fails due to permissions, consider as error
            return _error('cannot read directory entries')
        return _error('directory is neither root nor object')
    # Path is a file
    if os.path.isfile(abs_path):
        base = os.path.basename(abs_path)
        if re.match(r'^[0-9]+=.*$', base):
            return 'file'
        return _error('file does not match namaste pattern')
    return _error('unknown path type')

def deep_merge_nodes(nodes):
    '''
    Merge a list of (key_node, value_node) pairs deep by mapping nodes. If duplicate keys
    appear, merge their MappingNode values if both are mapping nodes; otherwise
    the later value wins.
    '''
    merged = {}  # key_value_str -> (key_node, value_node)

    for key_node, value_node in nodes:
        try:
            key = key_node.value
        except AttributeError:
            # Skip malformed key
            continue

        if key in merged:
            existing_key_node, existing_value_node = merged[key]
            # If both values are MappingNode, deep merge; else replace with the later node.
            if isinstance(existing_value_node, MappingNode) and isinstance(value_node, MappingNode):
                # Merge the mapping node pairs
                merged_pairs = deep_merge_nodes(existing_value_node.value + value_node.value)
                merged_mapping_node = MappingNode(
                    tag=existing_value_node.tag,
                    value=merged_pairs
                )
                merged[key] = (existing_key_node, merged_mapping_node)
            else:
                # Last value wins
                merged[key] = (existing_key_node, value_node)
        else:
            merged[key] = (key_node, value_node)

    return list(merged.values())

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate input
    if parser is None:
        raise ValueError("parser cannot be None")
    try:
        actions = getattr(parser, "_actions", None)
        if actions is None:
            raise TypeError("Provided object does not appear to be an ArgumentParser")
    except Exception as exc:
        raise TypeError("Provided object does not appear to be an ArgumentParser") from exc

    flags = []
    for action in actions:
        # Some actions (like epilog or description actions) might not have option_strings
        opt_strings = getattr(action, "option_strings", None)
        if opt_strings:
            for opt in opt_strings:
                if opt:  # filter out empty strings
                    flags.append(opt)

    # Preserve order and remove duplicates
    seen = set()
    unique_flags = []
    for f in flags:
        if f not in seen:
            seen.add(f)
            unique_flags.append(f)

    return " ".join(unique_flags)

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments
    and return them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    # Create the top‑level parser and a subparsers group.
    parser = argparse.ArgumentParser(add_help=False)
    subparsers = parser.add_subparsers(dest='subparser_name', required=False)

    # Parse the arguments, keeping any unrecognized tokens.
    try:
        namespace, remaining_args = parser.parse_known_args(unparsed_arguments)
    except Exception as exc:
        raise ValueError(f"Error while parsing arguments: {exc}") from exc

    # Determine the key for the result dictionary
    key = getattr(namespace, 'subparser_name', None)
    if not key:
        key = "global"

    # If a subparser was selected and there are remaining arguments,
    # attempt to parse them with that subparser's own parser.
    if key != "global" and remaining_args:
        # Find the corresponding subparser parser object
        subparser_obj = None
        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                subparser_obj = action.choices.get(key)
                break
        if subparser_obj:
            try:
                sub_namespace, sub_remaining = subparser_obj.parse_known_args(remaining_args)
                # Attach the subparser name for reference
                sub_namespace.subparser_name = key
                return {key: sub_namespace}
            except Exception as exc:
                raise ValueError(f"Error while parsing sub‑parser arguments for '{key}': {exc}") from exc

    # No subparser matched or no remaining args – return the top‑level namespace
    return {key: namespace}

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    The implementation below uses the node.tag attribute to differentiate a MappingNode from
    other node types. It recursively merges MappingNodes and preserves the order of keys from
    the first appearance.
    '''
    # Basic validation
    if not isinstance(nodes, list):
        raise ValueError('deep_merge_nodes expects a list of (ScalarNode, Node) tuples')

    def is_mapping(node):
        return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'

    def merge_mapping_nodes(node_a, node_b):
        """Recursively merge two MappingNode objects."""
        # node_a and node_b are expected to be MappingNode instances
        # Build an indexed dict from node_a's value list for quick lookup
        a_dict = {}
        for k, v in getattr(node_a, 'value', []):
            try:
                k_str = getattr(k, 'value', None)
            except Exception:
                continue
            a_dict[k_str] = (k, v)

        # Prepare output list starting from node_a's order
        merged_pairs = []
        for k, v in getattr(node_a, 'value', []):
            k_str = getattr(k, 'value', None)
            if k_str in a_dict:  # will always be true for this loop
                # will be overridden if node_b has this key
                merged_pairs.append((k, v))
        # Process node_b's pairs
        for k_b, v_b in getattr(node_b, 'value', []):
            try:
                k_str_b = getattr(k_b, 'value', None)
            except Exception:
                continue
            if k_str_b in a_dict:
                # key exists in node_a, replace value appropriately
                old_k, old_v = a_dict[k_str_b]
                if is_mapping(old_v) and is_mapping(v_b):
                    # both are mappings, merge recursively
                    merged_v = merge_mapping_nodes(old_v, v_b)
                else:
                    # otherwise, last wins: use v_b
                    merged_v = v_b
                # update in merged_pairs: find old_k's index
                for idx, (k_curr, _) in enumerate(merged_pairs):
                    if getattr(k_curr, 'value', None) == k_str_b:
                        merged_pairs[idx] = (old_k, merged_v)
                        break
            else:
                # new key, append
                merged_pairs.append((k_b, v_b))
                a_dict[k_str_b] = (k_b, v_b)

        # Construct a new MappingNode with merged pairs
        new_node = type(node_a)()
        new_node.tag = node_a.tag
        new_node.value = merged_pairs
        return new_node

    # Merge across duplicate keys
    merged_dict = {}
    key_node_map = {}
    for item in nodes:
        if not (isinstance(item, tuple) and len(item) == 2):
            raise ValueError('Each element of nodes must be a (key_node, value_node) tuple')
        key_node, val_node = item
        try:
            key_str = getattr(key_node, 'value', None)
        except Exception:
            raise ValueError('Key node must have a value attribute')
        if key_str in merged_dict:
            existing_val = merged_dict[key_str]
            if is_mapping(existing_val) and is_mapping(val_node):
                merged_val = merge_mapping_nodes(existing_val, val_node)
            else:
                merged_val = val_node  # last wins
            merged_dict[key_str] = merged_val
            key_node_map[key_str] = key_node  # keep latest key node (last wins)
        else:
            merged_dict[key_str] = val_node
            key_node_map[key_str] = key_node

    # Preserve order from the original nodes list
    result = []
    seen = set()
    for item in nodes:
        key_node, _ = item
        key_str = getattr(key_node, 'value', None)
        if key_str not in seen:
            seen.add(key_str)
            result.append((key_node_map[key_str], merged_dict[key_str]))
    return result

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Verify that the input has the expected interface
    if parser is None:
        raise TypeError("parser must not be None")
    try:
        actions = parser._actions
    except AttributeError as exc:
        raise TypeError("parser must be an argparse.ArgumentParser instance") from exc

    flags = []
    # Iterate over the actions in the order they were added
    for action in actions:
        # Each action may or may not have option_strings
        option_strings = getattr(action, "option_strings", [])
        # Ensure we only process string option names
        for opt in option_strings:
            if isinstance(opt, str):
                flags.append(opt)

    return " ".join(flags)

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    # Validate that dicts is iterable
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("Input must be an iterable of dictionaries")

    result = {}
    for d in iterator:
        # Validate that each item is a dictionary
        if not isinstance(d, dict):
            raise TypeError(f"Elements of input must be dictionaries; got {type(d).__name__}")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] = result[key] + value
                except Exception as exc:
                    raise TypeError(f"Could not add values for key '{key}': {exc}") from exc
            else:
                result[key] = value
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if val is None:
            return True
        if isinstance(val, str):
            s = val.strip().lower()
            return s in {"", "null", "none", "na", "nan", "nil", "void", "n/a", "n/a."}
        # If non-string, convert to string and check
        s = str(val).strip().lower()
        return s in {"", "null", "none", "na", "nan", "nil", "void", "n/a", "n/a."}
    except Exception:
        return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    import argparse
    try:
        if not isinstance(parser, argparse.ArgumentParser):
            raise TypeError("parser must be an argparse.ArgumentParser instance")
        flags = set()
        for action in getattr(parser, '_actions', []):
            option_strings = getattr(action, 'option_strings', None)
            if option_strings:
                flags.update(option_strings)
        return ' '.join(sorted(flags))
    except Exception as exc:
        raise RuntimeError(f"Failed to extract parser flags: {exc}") from exc

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    # Ensure arg is a string; if not, convert it to string representation
    arg_str = str(arg)
    try:
        return value.replace('.', arg_str)
    except Exception as exc:
        raise RuntimeError(f"Failed to replace '.' in string: {exc}") from exc

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("cls must be a class type")
    result = set()
    stack = [cls]
    while stack:
        parent = stack.pop()
        for sub in parent.__subclasses__():
            if sub not in result:
                result.add(sub)
                stack.append(sub)
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must contain at least one character")
    base = len(alphabet)
    # Map each character in the alphabet to its numeric value
    try:
        value_map = {ch: i for i, ch in enumerate(alphabet)}
    except TypeError as exc:
        raise TypeError("Alphabet must be a list of hashable characters") from exc

    num = 0
    for ch in string:
        if ch not in value_map:
            raise ValueError(f"Character '{ch}' not found in alphabet")
        num = num * base + value_map[ch]
    return num

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True if macOS
    :rtype: bool
    """
    try:
        # Prefer platform.system() for portability
        import platform
        return platform.system() == "Darwin"
    except Exception:
        # Fallback to os.uname() if platform import fails
        try:
            return os.uname().sysname == "Darwin"
        except Exception:
            return False

def unquote(name):
    """Remove quote from the given name."""
    try:
        if not isinstance(name, str):
            raise TypeError("name must be a string")
        # Strip leading and trailing single or double quotes.
        return name.strip('\'"')
    except Exception as exc:
        raise ValueError(f"Error removing quote: {exc}") from exc

import os, shlex

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    # Resolve platform flag
    if platform == 'this':
        current = os.name
        if current == 'nt':
            use_posix = False
        else:
            use_posix = True
    elif platform in ('1', 1):
        use_posix = True
    elif platform in ('0', 0):
        use_posix = False
    else:
        raise ValueError("Invalid platform value: must be 'this', 1 (POSIX) or 0 (Windows/CMD)")
    try:
        if use_posix:
            return shlex.split(s, posix=True)
        else:
            return shlex.split(s, posix=False)
    except ValueError as e:
        # re-raise with a clearer message
        raise ValueError(f"Unable to split command string: {e}") from e

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Validate input
    if not isinstance(host, str):
        return False
    host = host.strip()
    if not host:
        return False

    # Direct literal checks
    if host.lower() == "localhost":
        return True
    if host == "127.0.0.1":
        return True
    if host == "::1":
        return True

    # Resolve host to IP addresses and check if any is loopback
    try:
        # The port argument can be None because we only care about address resolution
        addrs = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
    except socket.gaierror:
        # Address resolution failed; not local
        return False
    except Exception:
        # Unexpected error; conservatively return False
        return False

    for family, _, _, _, sockaddr in addrs:
        # sockaddr is a tuple: (address, port) for IPv4
        # For IPv6, it may be (address, port, flowinfo, scopeid)
        try:
            ip = sockaddr[0]
        except Exception:
            continue

        # Check IPv4 loopback range 127.0.0.0/8
        if family == socket.AF_INET:
            if ip.startswith("127."):
                return True
        # Check IPv6 loopback ::1
        elif family == socket.AF_INET6:
            # Normalize IPv6 addressing: ::1 may appear in various forms
            if ip.lower() == "::1":
                return True

    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    import os

    # Validate input types
    if not isinstance(config_filename, (str, bytes, os.PathLike)):
        raise TypeError(f"config_filename must be a string, bytes, or PathLike object, got {type(config_filename).__name__}")
    if not isinstance(rendered_config, (str, bytes)):
        raise TypeError(f"rendered_config must be a string or bytes representing YAML content, got {type(rendered_config).__name__}")
    if not isinstance(mode, int):
        raise TypeError(f"mode must be an integer file mode, got {type(mode).__name__}")
    if not isinstance(overwrite, bool):
        raise TypeError(f"overwrite must be a bool, got {type(overwrite).__name__}")

    # Ensure config_filename is a string
    try:
        path = os.fspath(config_filename)
    except Exception as exc:
        raise TypeError(f"config_filename could not be converted to a filesystem path: {exc}") from exc

    # Create parent directories if they don't exist
    dir_path = os.path.dirname(path)
    if dir_path and not os.path.isdir(dir_path):
        try:
            os.makedirs(dir_path, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create directories '{dir_path}': {exc}") from exc

    # Check file existence
    if os.path.exists(path):
        if not overwrite:
            raise FileExistsError(f"File '{path}' already exists and overwrite=False")
        # if overwrite True, we proceed to overwrite

    # Write the content
    try:
        # Ensure rendered_config is str; if bytes, decode to str
        if isinstance(rendered_config, bytes):
            rendered_config = rendered_config.decode('utf-8')
        with open(path, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
        # Set file permissions
        try:
            os.chmod(path, mode)
        except OSError as exc:
            # If chmod fails, warn but still consider it a success
            pass
    except OSError as exc:
        raise OSError(f"Failed to write configuration to '{path}': {exc}") from exc

    return True

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Helper: Retrieve group from matcher if possible
    def _get_group(m, index, default=None):
        # If matcher is a regex Match object
        if hasattr(m, "group"):
            try:
                return m.group(index)
            except IndexError:
                return default
        # If matcher is an iterable (list/tuple) or mapping
        try:
            return m[index]
        except Exception:
            return default

    if matcher is None:
        raise ValueError("Matcher cannot be None")

    var_name = _get_group(matcher, 1)
    if not var_name:
        # try index 0 if match object didn't use capturing group
        var_name = _get_group(matcher, 0)
    default = _get_group(matcher, 2)

    if not var_name:
        raise ValueError("Environment variable name not provided in matcher")

    # Strip whitespace from variable name and default for safety
    var_name = var_name.strip()
    if default is not None:
        default = default.strip()

    # Attempt to fetch the environment variable
    try:
        value = os.getenv(var_name)
    except Exception as exc:
        raise RuntimeError(f"Failed to access environment variable '{var_name}': {exc}") from exc

    if value is None:
        if default is not None:
            return default
        else:
            raise KeyError(
                f"Environment variable '{var_name}' not found and no default value provided."
            )
    return value

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    # Handle None or non-string inputs
    if target is None:
        return False
    # If already an IPv4Address instance
    if isinstance(target, ipaddress.IPv4Address):
        return True
    # Try to parse the input as an IPv4 address
    try:
        ipaddress.IPv4Address(target)
        return True
    except (ipaddress.AddressValueError, ValueError, TypeError):
        return False

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input 'x' could not be converted to a numeric array.") from e

    mu = 0.2
    sigma = 0.1
    exponent = -((x_arr - mu) ** 2) / (2.0 * sigma ** 2)
    return np.exp(exponent)

def force_string(obj):
    """
    This function returns the bytes object corresponding to `obj`
    in case it is a string using UTF-8.
    """
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except Exception as exc:
            raise ValueError(f"Could not encode string to UTF-8: {exc}") from exc
    return obj

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        if values is None:
            raise ValueError("values must not be None")
        # Ensure values is iterable
        try:
            iterator = iter(values)
        except TypeError as exc:
            raise TypeError("values must be an iterable of strings") from exc

        # Collect cleaned strings; ignore non‑string entries
        cleaned = []
        for item in iterator:
            if not isinstance(item, str):
                continue
            text = item.strip()
            if text:
                cleaned.append(text)

        # Attempt to instantiate the class with the cleaned list.
        # If the constructor accepts a different signature, catch the
        # exception and surface a helpful error message.
        try:
            return cls(cleaned)
        except Exception as exc:  # pragma: no cover
            raise ValueError(
                f"Could not create {cls.__name__} from provided raw values: {exc}"
            ) from exc

def scale(self, other=None, recompute=False):
        """Compute or set scale (integral of the histogram).

        If *other* is ``None``, return scale of this histogram.
        If its scale was not computed before, it is computed and stored for subsequent
        use (unless explicitly asked to *recompute*).
        Note that after changing (filling) the histogram one must explicitly
        recompute the scale if it was computed before.

        If a float *other* is provided, rescale self to *other*.

        Histograms with scale equal to zero can't be rescaled.
        :exc:`.LenaValueError` is raised if one tries to do that.
        """
        # Helper to compute integral
        def _compute_integral():
            # Attempt to use a sum method or sum over stored values.
            if hasattr(self, "sum"):
                try:
                    return float(self.sum())
                except Exception:
                    pass
            # Fallback to summing over known data attributes
            if hasattr(self, "_values"):
                try:
                    return float(sum(self._values))
                except Exception:
                    pass
            if hasattr(self, "_b"):
                try:
                    return float(sum(self._b))
                except Exception:
                    pass
            # If nothing works, raise an informative error
            raise LenaValueError("Cannot compute scale: no data available")

        # If no new scale requested, return current scale (computing if needed)
        if other is None:
            if recompute or not hasattr(self, "_scale") or self._scale is None:
                # Recompute integral
                self._scale = _compute_integral()
            return self._scale

        # Attempt to rescale to a new value
        try:
            target = float(other)
        except Exception:
            raise TypeError(f"other must be None or convertible to a float, got {type(other).__name__}")

        # Get current scale (force recomputation)
        current_scale = _compute_integral()
        if current_scale == 0.0:
            raise LenaValueError("Histogram has zero scale; cannot rescale.")

        # Calculate scaling ratio
        ratio = target / current_scale

        # Apply scaling to histogram contents
        # Try to multiply the underlying data structures
        if hasattr(self, "_values"):
            try:
                self._values = [v * ratio for v in self._values]
            except Exception:
                # If it's a numpy array
                try:
                    self._values *= ratio
                except Exception:
                    pass
        elif hasattr(self, "_b"):
            try:
                self._b = [v * ratio for v in self._b]
            except Exception:
                try:
                    self._b *= ratio
                except Exception:
                    pass
        else:
            # If the object supports item assignment like a list
            try:
                for i in range(len(self)):
                    self[i] *= ratio
            except Exception as exc:
                raise LenaValueError("Unable to apply scaling to histogram") from exc

        # Store the new scale
        self._scale = target
        return None

def pop(self, key, default=__marker):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        try:
            value = self[key]
        except KeyError:
            if default is __marker:
                raise
            return default
        del self[key]
        return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Validate the cache has the expected attributes
    if not hasattr(self, "_cache"):
        raise AttributeError("The cache object does not have a `_cache` attribute.")
    if not hasattr(self, "_freq"):
        raise AttributeError("The cache object does not have a `_freq` attribute.")

    # Ensure the cache is not empty
    if not self._cache:
        raise KeyError("Pop from an empty cache.")

    # Find the minimum frequency among all keys
    try:
        min_freq = min(self._freq.values())
    except ValueError:
        # If _freq is empty (unlikely if _cache is not empty), raise an error
        raise KeyError("Pop from an empty cache (frequency data missing).")

    # Locate a key with the minimum frequency
    key_to_remove = None
    for key, freq in self._freq.items():
        if freq == min_freq:
            key_to_remove = key
            break

    if key_to_remove is None:
        # This situation indicates internal inconsistency
        raise RuntimeError("Could not find a key with the minimum frequency.")

    # Retrieve the value, remove the key from cache and frequency map
    value = self._cache.pop(key_to_remove)
    self._freq.pop(key_to_remove, None)

    return key_to_remove, value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Try to find the underlying dict-like structure that stores the items.
    data = getattr(self, "_data", None)
    if data is None:
        data = getattr(self, "data", None)
    if data is not None:
        # If the data structure is an OrderedDict (has popitem(last=...)).
        try:
            return data.popitem(last=False)
        except TypeError:
            # Fallback for plain dicts: pop the first key.
            if len(data) == 0:
                raise KeyError("popitem(): dictionary is empty")
            key = next(iter(data))
            value = data.pop(key)
            return key, value

    # If there is no single data attribute, look for separate order and cache lists.
    order = getattr(self, "_order", None)
    if order is None:
        order = getattr(self, "order", None)
    cache = getattr(self, "_cache", None)
    if cache is None:
        cache = getattr(self, "cache", None)
    if order is not None and cache is not None:
        if len(order) == 0:
            raise KeyError("popitem(): cache is empty")
        key = order.pop(0)
        value = cache.pop(key)
        return key, value

    # As a last resort, treat the instance itself as a dictionary.
    if isinstance(self, dict):
        if len(self) == 0:
            raise KeyError("popitem(): dictionary is empty")
        key = next(iter(self))
        value = self.pop(key)
        return key, value

    raise AttributeError("No suitable structure found to remove the least recently used item.")

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Ensure self behaves like a reversible collection
    try:
        rev_iter = reversed(self)
    except TypeError:
        raise TypeError(f"{type(self).__name__!r} object is not reversible") from None

    try:
        key = next(rev_iter)
    except StopIteration:
        # No items to pop
        raise KeyError("popitem(): dictionary is empty") from None

    try:
        value = self[key]
    except KeyError as exc:
        # This should not occur unless the mapping changed during iteration
        raise KeyError(f"Key {key!r} disappeared between retrieval and deletion") from exc

    try:
        del self[key]
    except Exception as exc:
        # In case deletion fails, propagate a clear error
        raise RuntimeError(f"Failed to delete key {key!r} during popitem: {exc}") from exc

    return key, value

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        # Matches `IN (param1, param2, ...)` with optional whitespace
        pattern_str = r'\bIN\s*\((?:\s*[^,\s()]+(?:\s*,\s*[^,\s()]+)*)\)'
        return re.compile(pattern_str, re.IGNORECASE)
    except re.error:
        # Fallback to a pattern that matches nothing
        return re.compile(r'$^')

def isoparse(self, dt_str):
    """Parse an ISO‑8601 datetime string into a :class:`datetime.datetime`."""

    # Guard the input type (the @_takes_ascii decorator guarantees a str-like object)
    if not isinstance(dt_str, (str, bytes)):
        raise TypeError(f"datetime string must be str or bytes, got {type(dt_str).__name__}")

    # Fallback: use the robust parser shipped in dateutil
    try:
        from dateutil import parser as _parser
    except Exception as exc:
        raise RuntimeError("dateutil is required for ISO parsing") from exc

    try:
        result = _parser.isoparse(dt_str)
    except Exception as exc:
        raise ValueError(f"Invalid ISO‑8601 datetime string: {dt_str}") from exc

    return result

def identify_request(request: RequestType):
    """
    Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # Check public message
        pub = getattr(request, 'public_message', None)
        if pub:
            if isinstance(pub, dict):
                if pub.get('type') == 'diaspora' or 'diaspora' in pub.values():
                    return True
            else:
                if 'diaspora' in str(pub).lower():
                    return True

        # Check private message
        priv = getattr(request, 'private_message', None)
        if priv:
            if isinstance(priv, dict):
                if priv.get('type') == 'diaspora' or 'diaspora' in priv.values():
                    return True
            else:
                if 'diaspora' in str(priv).lower():
                    return True

        # Check legacy payload
        legacy = getattr(request, 'legacy_payload', None)
        if legacy:
            if isinstance(legacy, dict):
                if legacy.get('isLegacy') or legacy.get('type') == 'legacy':
                    return True
            else:
                if 'legacy' in str(legacy).lower():
                    return True
    except Exception:
        # Gracefully handle any unexpected errors
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request.
    A Matrix request is typically an HTTP request whose path starts with
    "/_matrix" and whose content type or Accept header contains JSON.
    """
    try:
        # 1. Get the request path
        path = None
        if isinstance(request, dict):
            # Handle dict: could have 'path' or 'url'
            if "path" in request:
                path = request["path"]
            elif "url" in request:
                url = request["url"]
                # Strip query string if present
                path = url.split('?', 1)[0]
        else:
            # Try attribute access
            if hasattr(request, "path"):
                path = getattr(request, "path")
            elif hasattr(request, "url"):
                url = getattr(request, "url")
                path = url.split('?', 1)[0]
        if not isinstance(path, str):
            return False

        # 2. Check for Matrix path prefix
        if not path.startswith("/_matrix"):
            return False

        # 3. Verify JSON content type or Accept header
        headers = {}
        if isinstance(request, dict):
            headers = request.get("headers", {})
        else:
            if hasattr(request, "headers"):
                headers = getattr(request, "headers") or {}
        # Normalize header keys to lower-case
        headers_lc = {k.lower(): v for k, v in headers.items() if isinstance(k, str) and isinstance(v, str)}

        content_type = headers_lc.get("content-type", "")
        accept = headers_lc.get("accept", "")
        # Accept header might be a list of comma-separated values
        def contains_json(header_value):
            return "application/json" in header_value.lower()
        if contains_json(content_type) or contains_json(accept):
            return True

        # Default heuristic: if we have JSON body (not implemented due to lack of body param),
        # we would add more checks here. For now, return False if headers don't indicate JSON.
        return False
    except Exception:
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    if dt is None:
        raise ValueError("dt cannot be None")
    # Accept anything that provides a strftime method (datetime, date, etc.)
    if hasattr(dt, "strftime"):
        try:
            # Standard datetime format for D* nodes
            return dt.strftime("%Y-%m-%d %H:%M:%S")
        except Exception as exc:
            raise ValueError(f"Failed to format datetime: {exc}") from exc
    raise TypeError("dt must be a datetime-like object that supports strftime()")

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    Returns the Content-Type header value if available, otherwise None.
    """
    # Validate input
    if not isinstance(url, str) or not url.strip():
        return None

    try:
        import urllib.request
        import urllib.error
    except Exception:
        # urllib is not available
        return None

    try:
        # Prepare a HEAD request
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            # urllib returns an email.message.Message for headers
            content_type = resp.info().get_content_type()
            if content_type:
                return content_type
            # Fallback to explicit header retrieval
            return resp.info().get('Content-Type')
    except (urllib.error.HTTPError, urllib.error.URLError, ValueError):
        # Handle URL errors, HTTP errors, or malformed URLs
        return None
    except Exception:
        # Catch-all for any unexpected errors
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Basic checks for input type and non-empty string
    if not isinstance(tag, str):
        return False
    if not tag:
        return False

    # Define a simple tag rule: lowercase letters, digits, hyphens, no leading/trailing hyphens.
    # Max length 30 characters (arbitrary but reasonable).
    if len(tag) > 30:
        return False
    if tag[0] == '-' or tag[-1] == '-':
        return False

    # Use regex to ensure allowed characters only.
    import re
    pattern = re.compile(r'^[a-z0-9-]+$')
    if not pattern.match(tag):
        return False

    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    if node is None:
        return result
    try:
        for child in node:
            # If a tag occurs multiple times, the last occurrence wins.
            result[child.tag] = child
        return result
    except Exception as exc:
        raise ValueError(f"Failed to convert XML children to dict: {exc}") from exc

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate the base URL
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    trimmed_url = url.rstrip("/")
    if not (trimmed_url.startswith("http://") or trimmed_url.startswith("https://")):
        raise ValueError("url must start with http:// or https://")

    # Normalize the document path
    if document_path is None:
        document_path = "/.well-known/nodeinfo"
    else:
        if not isinstance(document_path, str):
            raise TypeError("document_path must be a string")
        # Ensure leading slash
        if not document_path.startswith("/"):
            document_path = "/" + document_path
        # Remove any trailing slash (but keep a leading slash)
        document_path = document_path.rstrip("/")

    base_href = trimmed_url + document_path

    # Create the NodeInfo .well-known document with links for both
    # schema v2.0 and v1.0 (the latter is optional if you wish).
    links = [
        {
            "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
            "href": f"{base_href}?schema=2.0",
        },
        {
            "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
            "href": f"{base_href}?schema=1.0",
        },
    ]

    return {"links": links}

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """

    # Helper for JSON parsing
    def _parse_json(doc: str) -> dict:
        import json
        data = json.loads(doc)
        # Expected new format
        subject = data.get("subject")
        aliases = data.get("aliases", [])
        # Links are stored under "_links"
        raw_links = data.get("_links", {})
        links = {}
        for rel, link_info in raw_links.items():
            if isinstance(link_info, dict):
                href = link_info.get("href")
                if href:
                    links[rel] = href
        return {"subject": subject, "aliases": aliases, "links": links}

    # Helper for old XRD parsing
    def _parse_xrd(doc: str) -> dict:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(doc)
        # The XRD namespace sometimes uses http://docs.oasis-open.org/wss/.. but we try no namespace too
        ns = {"xrd": "xri://$xrd*($v*2.0)"}
        subject_elem = root.find("xrd:Subject", ns) or root.find("Subject")
        subject = subject_elem.text if subject_elem is not None else None

        aliases = []
        for alias_elem in root.findall("xrd:Alias", ns) or root.findall("Alias"):
            if alias_elem.text:
                aliases.append(alias_elem.text)

        links = {}
        for link_elem in root.findall("xrd:Link", ns) or root.findall("Link"):
            rel = link_elem.get("rel")
            href = link_elem.get("href")
            if rel and href:
                links[rel] = href

        return {"subject": subject, "aliases": aliases, "links": links}

    if not isinstance(document, str):
        raise TypeError("document must be a string")

    doc = document.strip()
    if not doc:
        raise ValueError("empty document")

    # Try JSON first
    try:
        return _parse_json(doc)
    except Exception:
        pass

    # If JSON fails, try XRD
    try:
        return _parse_xrd(doc)
    except Exception as exc:
        raise ValueError(f"Unable to parse Diaspora webfinger document: {exc}") from exc

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    if not handle or '@' not in handle:
        return None
    user, domain = handle.split('@', 1)
    resource = f'acct:{handle}'
    try:
        parse_mod = __import__('urllib.parse')
        resource_enc = parse_mod.quote_plus(resource)
        url = f'https://{domain}/.well-known/webfinger?resource={resource_enc}'
        req_mod = __import__('urllib.request')
        req = req_mod.Request(url, headers={'Accept': 'application/json'})
        with req_mod.urlopen(req, timeout=5) as resp:
            # Some responses may not have getcode(), so use code attribute if absent
            code = getattr(resp, 'getcode', lambda: resp.code)()
            if code == 200:
                data = resp.read()
                try:
                    return data.decode('utf-8', errors='replace')
                except Exception:
                    return data.decode('latin1', errors='replace')
    except Exception:
        return None
    return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Validate the handle
    if not isinstance(handle, str) or not handle:
        raise ValueError("handle must be a non-empty string")
    if '@' not in handle:
        raise ValueError("handle must contain an '@' separating local part and domain")

    # Extract domain part for the URL
    _, domain = handle.split('@', 1)
    if not domain:
        raise ValueError("handle must contain a domain after '@'")

    # Construct the webfinger URL
    try:
        import urllib.request, urllib.parse, json, urllib.error
    except ImportError as e:
        raise RuntimeError("Required standard library modules are missing") from e

    resource = f"acct:{handle}"
    query = urllib.parse.urlencode({"resource": resource})
    webfinger_url = f"https://{domain}/.well-known/webfinger?{query}"

    # Prepare the request
    req = urllib.request.Request(webfinger_url, headers={"Accept": "application/jrd+json, application/json"})

    # Retrieve and parse
    try:
        with urllib.request.urlopen(req, timeout=10) as response:
            raw = response.read().decode("utf-8")
            return json.loads(raw)
    except urllib.error.HTTPError as e:
        raise RuntimeError(f"HTTP error retrieving webfinger for '{handle}': {e}") from e
    except urllib.error.URLError as e:
        raise RuntimeError(f"URL error retrieving webfinger for '{handle}': {e}") from e
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON response for webfinger '{handle}': {e}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error retrieving webfinger for '{handle}': {e}") from e

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    # Basic validation of input
    if not isinstance(host, str) or not host.strip():
        raise ValueError("host must be a non-empty string")

    # Ensure the host includes a scheme
    if not host.lower().startswith(("http://", "https://")):
        url = f"https://{host}"
    else:
        url = host

    # Build the well-known host‑meta URL
    if not url.endswith("/"):
        url += "/"
    url += ".well-known/host-meta"

    try:
        import urllib.request
        import urllib.error

        with urllib.request.urlopen(url, timeout=10) as resp:
            data = resp.read()
    except urllib.error.HTTPError as err:
        raise RuntimeError(f"HTTP error retrieving host-meta from {url}: {err}") from err
    except urllib.error.URLError as err:
        raise RuntimeError(f"URL error retrieving host-meta from {url}: {err}") from err
    except Exception as err:  # pragma: no cover
        raise RuntimeError(f"Unexpected error retrieving host-meta from {url}: {err}") from err

    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(data)
    except ET.ParseError as err:  # pragma: no cover
        raise RuntimeError(f"Failed to parse host-meta XML from {url}") from err

    class XRD:
        """Simple wrapper representing the parsed XRD data."""
        def __init__(self, element):
            self.element = element

        def __repr__(self):
            return f"<XRD tag={self.element.tag}>"

    return XRD(root)

@classmethod
    def workspace_manager(cls):
        """Gets the workspace manager."""
        try:
            return getattr(cls, "_workspace_manager")
        except AttributeError as exc:
            raise AttributeError("Workspace manager is not configured on the class.") from None

@classmethod
def plugins_manager(cls):
    """Gets the plugin manager."""
    try:
        if hasattr(cls, "_plugin_manager"):
            return cls._plugin_manager
        # Define a simple plugin manager on the fly
        class _PluginManager:
            def __init__(self):
                self.plugins = {}

            def register(self, name, plugin):
                """Register a plugin by name."""
                if not isinstance(name, str):
                    raise TypeError("Plugin name must be a string")
                self.plugins[name] = plugin

            def get(self, name):
                """Retrieve a plugin by name."""
                return self.plugins.get(name)

            def list(self):
                """Return a list of all registered plugin names."""
                return list(self.plugins.keys())

        cls._plugin_manager = _PluginManager()
        return cls._plugin_manager
    except Exception as exc:
        raise RuntimeError(f"Could not create or retrieve plugin manager: {exc}") from exc

@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        try:
            if spec_content is None:
                raise IRValidatorException("Spec content is None")
            if not isinstance(spec_content, dict):
                raise IRValidatorException("Spec content must be a dictionary")

            required_fields = ["apiVersion", "kind", "metadata", "spec"]
            missing = [f for f in required_fields if f not in spec_content]
            if missing:
                raise IRValidatorException(
                    f"Missing required fields in spec: {', '.join(missing)}"
                )
            return spec_content
        except IRValidatorException:
            raise
        except Exception as exc:
            raise IRValidatorException(f"Error validating spec content: {exc}") from exc

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    This method looks for an ``include`` key in ``parser_dict`` that
    specifies one or more group names whose definitions should be merged
    into the current dictionary.  The merge is deep so that nested
    dictionaries are combined rather than replaced.  Group definitions
    are obtained from the instance via ``self.get_group(name)`` or,
    falling back, from ``self._api_groups``.  Any missing group will
    raise a :class:`KeyError`.  Non‑string include entries or a
    non‑dict parser will raise :class:`TypeError`.

    The function modifies ``parser_dict`` in place and does not return
    a value.
    """
    # Validate input
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dictionary.")

    # Retrieve and remove the include directive
    include = parser_dict.pop("include", None)
    if include is None:
        # Nothing to include – return immediately
        return

    # Normalise to a list of strings
    if isinstance(include, str):
        include = [include]
    if not isinstance(include, list):
        raise TypeError("'include' directive must be a string or list of strings.")
    for item in include:
        if not isinstance(item, str):
            raise TypeError("Include group names must be strings.")

    # Helper for deep dictionary merge
    def _deep_merge(dest, src):
        for key, value in src.items():
            if key == "include":
                # Avoid re‑introducing the include key
                continue
            if (
                key in dest
                and isinstance(dest[key], dict)
                and isinstance(value, dict)
            ):
                _deep_merge(dest[key], value)
            else:
                dest[key] = value

    # Helper to fetch a group definition
    def _fetch_group(name):
        if hasattr(self, "get_group") and callable(self.get_group):
            return self.get_group(name)
        if hasattr(self, "_api_groups") and isinstance(self._api_groups, dict):
            return self._api_groups.get(name)
        return None

    # Use an attribute to keep track of already‑processed groups
    if not hasattr(self, "_groups_included"):
        self._groups_included = set()

    for group_name in include:
        if group_name in self._groups_included:
            continue  # Prevent infinite recursion for cyclic includes
        self._groups_included.add(group_name)

        group_dict = _fetch_group(group_name)
        if group_dict is None:
            raise KeyError(f"Group '{group_name}' not found for include directive.")
        if not isinstance(group_dict, dict):
            raise TypeError(f"Group '{group_name}' must be a dictionary.")

        _deep_merge(parser_dict, group_dict)

        # Recursively process any includes inside the added group
        self._include_groups(parser_dict)

    # Clear the include tracking for subsequent calls
    if hasattr(self, "_groups_included"):
        self._groups_included.clear()

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        # Fetch spec, which is expected to be a mapping containing argument definitions
        spec = getattr(self, 'spec', None)
        if not spec:
            return defaults

        # Accept spec in dict form with an 'args' list, or simply a list of arg dicts
        if isinstance(spec, dict):
            args_iterable = spec.get('args', [])
        else:
            args_iterable = []

        for arg in args_iterable:
            try:
                if not isinstance(arg, dict):
                    continue
                name = arg.get('name')
                if not name:
                    continue
                # Prefer explicit default from spec
                value = arg.get('default')
                # If spec default missing, try to get attribute with same name followed by '_default'
                if value is None:
                    alt_attr = f"{name}_default"
                    if hasattr(self, alt_attr):
                        value = getattr(self, alt_attr)
                defaults[name] = value
            except Exception:
                # Skip problematic arg entries
                continue
    except Exception:
        # Any issue fetching spec or processing its contents is silently ignored
        pass
    return defaults

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Basic type checks
    if not isinstance(cli_args, dict):
        raise TypeError("cli_args must be a dictionary")
    if not isinstance(answer_file_args, dict):
        raise TypeError("answer_file_args must be a dictionary")

    # Helper to fetch deprecated mapping from the instance in a robust way
    deprecated_map = None
    possible_attrs = [
        "deprecated_args",
        "deprecated_cli_args",
        "deprecated_answer_file_args",
        "deprecated_arguments",
    ]
    for attr in possible_attrs:
        deprecated_map = getattr(self, attr, None)
        if isinstance(deprecated_map, dict):
            break
    if not isinstance(deprecated_map, dict):
        # Nothing to validate
        return

    # Process CLI arguments
    for old_key, new_key in list(deprecated_map.items()):
        if not isinstance(old_key, str) or not isinstance(new_key, str):
            continue  # skip malformed mapping entries
        if old_key in cli_args:
            print(
                f"WARNING: argument '{old_key}' is deprecated. "
                f"Please use '{new_key}' instead."
            )
            # Promote to the new key if it does not already exist
            if new_key not in cli_args:
                cli_args[new_key] = cli_args.pop(old_key)
            else:
                # If both old and new exist, prefer the CLI's new value
                cli_args.pop(old_key)

    # Process answer-file arguments
    for old_key, new_key in list(deprecated_map.items()):
        if not isinstance(old_key, str) or not isinstance(new_key, str):
            continue  # skip malformed entries
        if old_key in answer_file_args:
            # If the user supplied the new key on the CLI, drop the deprecated one
            if new_key in cli_args:
                answer_file_args.pop(old_key)
                continue
            # Otherwise promote the value to the new key
            print(
                f"WARNING: argument '{old_key}' in the answer file is "
                f"deprecated. Please use '{new_key}' instead."
            )
            if new_key not in answer_file_args:
                answer_file_args[new_key] = answer_file_args.pop(old_key)
            else:
                # If both old and new are present in the file, prefer the new
                answer_file_args.pop(old_key)

    # No return value is necessary; modifications are made in-place
    return None

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str) or not command_name.strip():
        return []

    command_name = command_name.strip()
    cmd_obj = None

    # Attempt to fetch the command object from the parser
    try:
        if hasattr(self, "parser") and hasattr(self.parser, "commands"):
            cmd_obj = self.parser.commands.get(command_name)
            if cmd_obj is None:
                # Fall back to case‑insensitive lookup
                cmd_obj = self.parser.commands.get(command_name.lower())
    except Exception:
        # Any unexpected error while accessing the parser structure
        return []

    if cmd_obj is None:
        return []

    # Extract option specifications from the command object
    try:
        # Common attribute names that might hold the options
        if hasattr(cmd_obj, "option_specs"):
            return list(cmd_obj.option_specs)
        if hasattr(cmd_obj, "options"):
            opts = getattr(cmd_obj, "options")
            if isinstance(opts, dict):
                return list(opts.values())
            if isinstance(opts, (list, tuple)):
                return list(opts)

        # If the command is an argparse.ArgumentParser, return its actions
        if hasattr(cmd_obj, "_actions"):
            return list(cmd_obj._actions)
    except Exception:
        # If any error occurs while reading the options, return an empty list
        return []

    return []

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Validate inputs
    if not isinstance(command_name, str):
        raise TypeError(f"command_name must be a string, got {type(command_name).__name__}")
    if not isinstance(argument_name, str):
        raise TypeError(f"argument_name must be a string, got {type(argument_name).__name__}")

    try:
        cmd = self._commands[command_name]
    except (AttributeError, KeyError) as exc:
        # Either the class does not have _commands or the command is missing
        raise KeyError(f"Command '{command_name}' not found") from exc

    # Attempt to retrieve the option specification
    if hasattr(cmd, 'options') and isinstance(cmd.options, dict):
        if argument_name in cmd.options:
            return cmd.options[argument_name]
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")
    elif hasattr(cmd, 'get_option') and callable(cmd.get_option):
        try:
            return cmd.get_option(argument_name)
        except Exception as exc:
            raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'") from exc
    else:
        raise AttributeError(
            f"Command object for '{command_name}' does not expose options or a get_option method"
        )

def get_silent_args(self, args):
    """
    Return a list of argument names that are considered "silent".
    Arguments that start with an underscore (e.g., '_private') are treated as silent.
    The input `args` can be a dictionary mapping argument names to values, or an iterable of
    (name, value) pairs. If the input type does not match either expected form, an empty
    list is returned.

    :param args: The received arguments, typically a dictionary or an iterable of name/value pairs.
    :return: list of silent argument names.
    """
    silent_args = []
    try:
        # If args is a dictionary, check keys
        if isinstance(args, dict):
            for key in args:
                if isinstance(key, str) and key.startswith("_"):
                    silent_args.append(key)
        else:
            # Try treating args as an iterable of pairs (name, value)
            for item in args:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    name, _ = item
                    if isinstance(name, str) and name.startswith("_"):
                        silent_args.append(name)
    except Exception:
        # In case of unexpected structure or errors, return empty list
        return []
    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure the class defines which arguments are required
    if not hasattr(self, "required_args"):
        raise AttributeError("The instance has no attribute 'required_args' to validate against.")
    required = getattr(self, "required_args")
    if not isinstance(required, (list, set, tuple)):
        raise TypeError("Attribute 'required_args' must be a list, set, or tuple of argument names.")
    # Normalize arguments container for checking
    missing = []
    if args is None:
        raise TypeError("The 'args' parameter cannot be None.")
    if isinstance(args, dict):
        for key in required:
            if key not in args or args[key] is None:
                missing.append(key)
    else:
        # Try attribute access for non-mapping objects (e.g., argparse.Namespace)
        for key in required:
            if not hasattr(args, key) or getattr(args, key) is None:
                missing.append(key)
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        # Helper to evaluate a requirement condition against the provided args.
        def _evaluate(cond, available):
            if isinstance(cond, str):
                # Try to evaluate an expression; fall back to simple lookup.
                try:
                    return bool(
                        eval(cond, {"__builtins__": None}, available)
                    )
                except Exception:
                    return bool(available.get(cond))
            # If the condition is not a string, treat truthiness directly.
            return bool(cond)

        # Normalise the args into a mapping for easy lookup.
        arg_map = {}
        if isinstance(args, dict):
            arg_map = args
        elif isinstance(args, list):
            for item in args:
                if isinstance(item, (tuple, list)) and len(item) == 2:
                    key, value = item
                    arg_map[key] = value

        if not isinstance(options_spec, (list, tuple)):
            raise ValueError(
                "options_spec must be a list or tuple of option spec dicts"
            )

        required = []
        for opt in options_spec:
            if not isinstance(opt, dict):
                continue
            cond = opt.get("required_when")
            if cond is None:
                continue
            try:
                # If the condition is a list or tuple of multiple checks, any True qualifies.
                if isinstance(cond, (list, tuple)):
                    matched = any(_evaluate(c, arg_map) for c in cond)
                else:
                    matched = _evaluate(cond, arg_map)
            except Exception:
                # If evaluation fails, skip this option.
                matched = False
            if matched:
                name = opt.get("name")
                if name:
                    required.append(name)
        return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    :raises TypeError: If args is not a mapping.
    :raises ValueError: If an argument value exceeds its specified maximum length.
    """
    # Ensure args is a mapping (dict-like)
    if not isinstance(args, dict):
        raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")

    # Attempt to retrieve length specifications from the instance.
    # Convention: subclass may define self.arg_lengths as a dict mapping argument names
    # to maximum allowed length (int), or provide a method get_arg_length(name).
    length_spec = None
    if hasattr(self, 'arg_lengths'):
        length_spec = getattr(self, 'arg_lengths')
    elif hasattr(self, 'get_arg_length') and callable(getattr(self, 'get_arg_length')):
        def get_spec(name):
            try:
                return self.get_arg_length(name)
            except Exception:
                return None
        length_spec = get_spec
    else:
        length_spec = None

    for key, value in args.items():
        # Determine expected maximum length
        # If length_spec is dict
        if isinstance(length_spec, dict):
            max_len = length_spec.get(key)
        # If length_spec is a callable that returns length
        elif callable(length_spec):
            try:
                max_len = length_spec(key)
            except Exception:
                max_len = None
        else:
            max_len = None

        # If no length specified, skip validation
        if max_len is None:
            continue

        # Only strings or collections have length
        try:
            actual_len = len(value)
        except Exception:
            # If value has no length, we cannot validate; skip
            continue

        if actual_len > max_len:
            raise ValueError(
                f"Argument '{key}' length {actual_len} exceeds allowed maximum of {max_len}"
            )

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # It is assumed that the instance has an attribute `choices`
    # which is a mapping from argument names to an iterable of
    # allowed values (e.g. a list or a set).
    # If no such attribute exists, nothing to validate.
    try:
        expected_choices = getattr(self, 'choices', {})
        if not isinstance(expected_choices, dict):
            # If the attribute is not a dict, fall back to empty mapping.
            expected_choices = {}
    except Exception:
        expected_choices = {}

    for arg_name, value in args.items():
        # Skip arguments that are not defined as choice arguments
        if arg_name not in expected_choices:
            continue

        valid = expected_choices[arg_name]
        # Ensure valid is iterable
        try:
            valid_iter = iter(valid)
        except TypeError:
            raise TypeError(f"Choices for argument '{arg_name}' must be an iterable, got {type(valid).__name__}")

        # Convert to a set for efficient containment checks
        choices_set = set(valid_iter)
        if value not in choices_set:
            # Provide a clear error message
            raise ValueError(
                f"Invalid value for argument '{arg_name}': {value!r} "
                f"is not among the allowed choices: {sorted(choices_set)}"
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if args is None:
        return
    if not isinstance(args, dict):
        raise TypeError("args must be a dict of argument names to values")
    # Retrieve the specification that may contain min/max bounds
    spec = getattr(self, "input_spec", None)
    if spec is None or not isinstance(spec, dict):
        # No specification provided; nothing to validate
        return
    for key, value in args.items():
        if key not in spec:
            # Argument not defined in the spec; skip validation
            continue
        arg_spec = spec[key]
        if not isinstance(arg_spec, dict):
            continue
        min_val = arg_spec.get("min")
        max_val = arg_spec.get("max")
        if min_val is None or max_val is None:
            # If one of the bounds is missing, skip validation for this argument
            continue
        try:
            if not (min_val <= value <= max_val):
                raise ValueError(
                    f"Argument '{key}'={value} out of range [{min_val}, {max_val}]"
                )
        except TypeError as exc:
            # Value cannot be compared to the bounds (e.g., different types)
            raise TypeError(
                f"Argument '{key}'={value} cannot be compared to bounds [{min_val}, {max_val}]"
            ) from exc

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    if not isinstance(subcommand, str):
        raise TypeError(f"subcommand must be a string, got {type(subcommand).__name__}")
    if not isinstance(type_name, str):
        raise TypeError(f"type_name must be a string, got {type(type_name).__name__}")
    if not isinstance(option_name, str):
        raise TypeError(f"option_name must be a string, got {type(option_name).__name__}")
    if not isinstance(spec_option, dict):
        raise TypeError(f"spec_option must be a dict, got {type(spec_option).__name__}")

    # Inner class representing the complex argument type
    class ComplexArgumentType:
        def __init__(self, subcommand, type_name, option_name, spec_option):
            self.subcommand = subcommand
            self.type_name = type_name
            self.option_name = option_name
            self.spec_option = spec_option

        def __repr__(self):
            return (f"<ComplexArgumentType subcommand={self.subcommand!r} "
                    f"type_name={self.type_name!r} option_name={self.option_name!r}>")

        def parse(self, value):
            """
            Parse a string value into the desired complex type.  The spec_option
            may contain a 'type' key mapping to a callable responsible for
            performing the conversion.
            """
            type_func = self.spec_option.get('type', str)
            try:
                return type_func(value)
            except Exception as exc:
                raise ValueError(
                    f"Failed to parse value '{value}' for option '{self.option_name}' "
                    f"using type {type_func!r}: {exc}"
                ) from exc

    # Return an instance of the inner class
    return ComplexArgumentType(subcommand, type_name, option_name, spec_option)

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        control_args = {}
        nested_args = {}
        # Accept dict or list/tuple of key/value pairs
        try:
            if isinstance(args, dict):
                args_dict = args
            else:
                # Try to convert to dict
                args_dict = dict(args)
        except Exception:
            # If unable to interpret, return empty dicts
            return ({}, {})
        for k, v in args_dict.items():
            # Treat keys beginning with '_' as control arguments
            if isinstance(k, str) and k.startswith("_"):
                control_args[k] = v
            # Treat keys beginning with 'custom_' as custom arguments
            elif isinstance(k, str) and k.startswith("custom_"):
                # custom args are kept separate but not returned per signature
                # we simply skip adding them to nested, as they are not standard
                # behaviour. They could be merged into nested if needed.
                continue
            else:
                nested_args[k] = v
        return (control_args, nested_args)

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``.

        :param vars_dict: Dictionary to merge extra-vars into.
        :param extra_vars: Iterable of extra-vars; each item may be a ``dict`` or a string
            of the form ``key=value`` or ``key1=value1,key2=value2``.  If ``None`` no action
            is taken.  The function returns the updated dictionary.

        :raises TypeError: if ``vars_dict`` is not a dictionary or ``extra_vars`` contains
            unsupported types.
        :raises ValueError: if an entry in ``extra_vars`` cannot be parsed.
        """
        if not isinstance(vars_dict, dict):
            raise TypeError('vars_dict must be a dictionary')
        if extra_vars is None:
            return vars_dict

        # Ensure we can iterate over extra_vars
        try:
            extras = list(extra_vars)
        except TypeError:
            raise TypeError('extra_vars must be an iterable')

        for item in extras:
            if isinstance(item, dict):
                # Merge dictionary entries directly
                vars_dict.update(item)
            elif isinstance(item, str):
                # Split on commas to allow bulk assignments like 'a=1,b=2'
                parts = [p.strip() for p in item.split(',') if p.strip()]
                for part in parts:
                    if '=' not in part:
                        raise ValueError(f'Invalid extra var format "{part}". Expected "key=value".')
                    key, value = part.split('=', 1)
                    vars_dict[key] = value
            else:
                raise TypeError(f'Unsupported type {type(item).__name__} in extra_vars')

        return vars_dict

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """
    Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
        workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results as a dictionary containing stdout, stderr, and returncode
    """
    import json
    import subprocess
    import os

    # Validate input types
    if cli_args is None:
        cli_args = []
    if not isinstance(cli_args, list):
        # Attempt to split a single string into arguments
        if isinstance(cli_args, str):
            cli_args = cli_args.split()
        else:
            raise ValueError("cli_args must be a list or string")

    if vars_dict is None:
        vars_dict = {}
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    # Determine the working directory from the workspace object
    workspace_path = None
    if ir_workspace is not None:
        # Try common attribute/method names
        if hasattr(ir_workspace, "get_path") and callable(ir_workspace.get_path):
            try:
                workspace_path = ir_workspace.get_path()
            except Exception:
                workspace_path = None
        if workspace_path is None and hasattr(ir_workspace, "path"):
            workspace_path = ir_workspace.path
        if workspace_path is None and hasattr(ir_workspace, "root"):
            workspace_path = ir_workspace.root

    if workspace_path is None:
        workspace_path = os.getcwd()

    # Prepare the command
    cmd = list(cli_args)  # copy to avoid side effects
    try:
        # Ensure we pass extra-vars as a JSON string
        extra_vars_json = json.dumps(vars_dict)
    except (TypeError, ValueError) as e:
        raise ValueError(f"Failed to serialize vars_dict to JSON: {e}") from e

    cmd.extend(["--extra-vars", extra_vars_json])

    # Run the command
    try:
        completed = subprocess.run(
            cmd,
            cwd=workspace_path,
            capture_output=True,
            text=True,
            check=False  # we handle non-zero stubs ourselves
        )
    except OSError as e:
        # Unable to execute the command
        return {
            "stdout": "",
            "stderr": f"Execution failed: {e}",
            "returncode": -1
        }
    except Exception as e:
        return {
            "stdout": "",
            "stderr": f"Unexpected error: {e}",
            "returncode": -1
        }

    return {
        "stdout": completed.stdout,
        "stderr": completed.stderr,
        "returncode": completed.returncode
    }

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to the correct types by modifying the supplied values_dict in-place.

        Args:
            parser_name (str): The command name, e.g. 'main', 'virsh', 'ospd', etc.
            values_dict (dict): Dictionary of argument names to values (typically all strings).

        This method looks up a mapping of argument names to target types for the given
        parser_name. If a mapping entry exists, the value is converted to that type.
        Supported target types are ``int``, ``float``, ``bool``, ``list`` and ``dict``.
        Conversion failures raise a ``ValueError`` with a helpful message.

        The method returns ``None`` but mutates *values_dict*.
        """
        # Retrieve type mapping for this parser, if any.
        # Derived classes may define _ARG_TYPES = {parser_name: {arg_name: type, ...}}
        type_map = getattr(self, "_ARG_TYPES", {}).get(parser_name, {})

        if not type_map:
            # Nothing to convert; return early.
            return

        for key, target_type in type_map.items():
            if key not in values_dict:
                continue  # Skip missing keys.

            raw_value = values_dict[key]
            # Skip conversion if already of correct type.
            if isinstance(raw_value, target_type):
                continue

            try:
                if target_type is int:
                    values_dict[key] = int(raw_value)
                elif target_type is float:
                    values_dict[key] = float(raw_value)
                elif target_type is bool:
                    # Accept common string representations of booleans.
                    if isinstance(raw_value, str):
                        lowered = raw_value.lower()
                        if lowered in {"true", "1", "yes", "on"}:
                            values_dict[key] = True
                        elif lowered in {"false", "0", "no", "off"}:
                            values_dict[key] = False
                        else:
                            raise ValueError(f"Cannot convert {raw_value!r} to bool")
                    else:
                        values_dict[key] = bool(raw_value)
                elif target_type is list:
                    # Assume comma separated values for strings; preserve existing list.
                    if isinstance(raw_value, str):
                        values_dict[key] = [item.strip() for item in raw_value.split(",") if item.strip()]
                    elif isinstance(raw_value, (list, tuple)):
                        values_dict[key] = list(raw_value)
                    else:
                        # Wrap single value in a list.
                        values_dict[key] = [raw_value]
                elif target_type is dict:
                    # Attempt to parse JSON string if necessary.
                    import json
                    if isinstance(raw_value, str):
                        values_dict[key] = json.loads(raw_value)
                    elif isinstance(raw_value, dict):
                        values_dict[key] = raw_value
                    else:
                        raise ValueError(f"Cannot convert {raw_value!r} to dict")
                else:
                    # Unknown target type: attempt to cast directly.
                    values_dict[key] = target_type(raw_value)

            except (TypeError, ValueError) as exc:
                msg = (
                    f"Error converting argument '{key}' (value={raw_value!r}) "
                    f"to type {target_type.__name__} for parser '{parser_name}': {exc}"
                )
                # If a logger is available on the instance, use it; otherwise raise.
                logger = getattr(self, "_logger", None)
                if logger and hasattr(logger, "error"):
                    logger.error(msg)
                raise ValueError(msg) from exc

        # No return value needed; values_dict mutated in-place.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Search for a plugin specification file
    spec_file = None
    for file_name in ("plugin.json", "plugin.yaml", "plugin.yml"):
        potential_path = os.path.join(plugin_dir, file_name)
        if os.path.isfile(potential_path):
            spec_file = potential_path
            break

    if not spec_file:
        raise FileNotFoundError(f"No plugin specification file found in {plugin_dir}")

    # Load the spec (JSON first, fallback to YAML if JSON fails)
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        try:
            import yaml

            with open(spec_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except Exception as e:
            raise ValueError(f"Unable to load plugin spec: {e}") from e

    if not isinstance(data, dict):
        raise ValueError("The plugin spec must contain a top-level dictionary")

    # Helper to flatten nested dictionaries and lists
    flat_dict = {}

    def _flatten(current, parent_key=""):
        if isinstance(current, dict):
            for k, v in current.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                _flatten(v, new_key)
        elif isinstance(current, list):
            for idx, item in enumerate(current):
                new_key = f"{parent_key}[{idx}]"
                _flatten(item, new_key)
        else:
            flat_dict[parent_key] = current

    _flatten(data)
    return flat_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    env_var = "CONFIG_PATH"
    try:
        if env_var not in os.environ:
            # Determine a default configuration file path.
            # Prefer relative to this file's directory, fallback to current working directory.
            if "__file__" in globals():
                default_path = os.path.join(os.path.dirname(__file__), "config.yaml")
            else:
                default_path = os.path.join(os.getcwd(), "config.yaml")
            os.environ[env_var] = default_path
    except Exception:
        # Silently ignore any error (e.g., missing __file__ or permission issues)
        pass
